import re
import requests
from datetime import datetime

URL = 'https://www.cnb.cz/cs/financni-trhy/devizovy-trh/kurzy-devizoveho-trhu/kurzy-devizoveho-trhu/denni_kurz.txt'


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    amount = inp.get('amount')
    cur = inp.get('currency')
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise ValueError('amount must be a number')
    if not isinstance(cur, str) or not re.fullmatch(r'\s*[A-Za-z]{3}\s*', cur):
        raise ValueError('currency must be a 3-letter code')
    cur = cur.strip().upper()
    params = {}
    d = inp.get('date')
    if d is not None:
        if not isinstance(d, str):
            raise ValueError('date must be a string DD.MM.YYYY')
        try:
            datetime.strptime(d, '%d.%m.%Y')
        except ValueError:
            raise ValueError('date must be formatted DD.MM.YYYY')
        params['date'] = d
    r = requests.get(URL, params=params, timeout=15)
    if r.status_code != 200:
        raise ValueError(f'CNB request failed with status {r.status_code}')
    r.encoding = 'utf-8'
    lines = r.text.strip().splitlines()
    if len(lines) < 3:
        raise ValueError('unexpected CNB response')
    rate_date = lines[0].split()[0]
    iso = datetime.strptime(rate_date, '%d.%m.%Y').date().isoformat()
    for line in lines[2:]:
        p = line.split('|')
        if len(p) == 5 and p[3] == cur:
            unit = float(p[2].replace(',', '.'))
            rate = float(p[4].replace(',', '.'))
            czk = round(amount * rate / unit, 2)
            return {'amount': amount, 'currency': cur, 'rate': rate, 'unit_amount': unit, 'czk': czk, 'rate_date': iso}
    if cur == 'CZK':
        return {'amount': amount, 'currency': cur, 'rate': 1.0, 'unit_amount': 1.0, 'czk': float(amount), 'rate_date': iso}
    raise ValueError(f'currency {cur} not found in CNB rate list')

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    convs = inp.get('conversions')
    if not isinstance(convs, list) or not convs:
        raise ValueError('conversions must be a non-empty list')
    best = {}
    dates = []
    for i, c in enumerate(convs):
        if not isinstance(c, dict):
            raise ValueError(f'conversion {i} must be an object')
        cur = c.get('currency')
        if not isinstance(cur, str) or not cur.strip():
            raise ValueError(f'conversion {i} missing currency')
        rate = c.get('rate')
        unit = c.get('unit_amount', 1)
        for name, v in (('rate', rate), ('unit_amount', unit)):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f'conversion {i} has invalid {name}')
        if rate <= 0 or unit <= 0:
            raise ValueError(f'conversion {i} rate and unit_amount must be positive')
        best[cur.strip().upper()] = rate / unit
        d = c.get('rate_date')
        if isinstance(d, str) and d:
            dates.append(d)
    ranking = [{'currency': k, 'czk_per_unit': round(v, 6)} for k, v in sorted(best.items(), key=lambda kv: (-kv[1], kv[0]))]
    out = {'ranking': ranking, 'strongest': ranking[0]['currency'], 'weakest': ranking[-1]['currency']}
    if dates:
        out['rate_date'] = max(dates)
    return out

