SYMBOLS = {'€': 'EUR', '$': 'USD', '£': 'GBP', '¥': 'JPY', 'KČ': 'CZK'}


def parse_amount(a):
    if a is None:
        return 1
    if isinstance(a, bool):
        raise ValueError('amount must be a number')
    if isinstance(a, (int, float)):
        if a != a or a in (float('inf'), float('-inf')):
            raise ValueError('amount must be a finite number')
        return a
    if not isinstance(a, str):
        raise ValueError('amount must be a number or numeric string')
    if not a.strip():
        return 1
    s = re.sub(r'[\s\u00a0\u202f\'’]', '', a)
    s = re.sub(r'[^\d,.\-+]', '', s)
    if not re.search(r'\d', s):
        raise ValueError('amount must be a number')
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        if s.count(',') > 1:
            s = s.replace(',', '')
        else:
            s = s.replace(',', '.')
    elif s.count('.') > 1:
        s = s.replace('.', '')
    try:
        v = float(s)
    except ValueError:
        raise ValueError('amount must be a number')
    return int(v) if v == int(v) and '.' not in s else v


def parse_currency(c):
    if not isinstance(c, str):
        raise ValueError('currency must be a 3-letter code')
    s = c.strip()
    if s.upper() in SYMBOLS:
        return SYMBOLS[s.upper()]
    if s in SYMBOLS:
        return SYMBOLS[s]
    k = re.sub(r'[^A-Za-z]', '', s).upper()
    if k in ALIASES:
        return ALIASES[k]
    if re.fullmatch(r'[A-Z]{3}', k):
        return k
    raise ValueError('currency must be a 3-letter code')


def fetch(d, cache):
    if d in cache:
        return cache[d]
    params = {'date': d} if d else {}
    r = requests.get(URL, params=params, timeout=15)
    if r.status_code != 200:
        raise ValueError(f'CNB request failed with status {r.status_code}')
    r.encoding = 'utf-8'
    lines = r.text.strip().splitlines()
    if len(lines) < 3:
        raise ValueError('unexpected CNB response')
    iso = datetime.strptime(lines[0].split()[0], '%d.%m.%Y').date().isoformat()
    cache[d] = (iso, lines[2:])
    return cache[d]


def single(inp, cache):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    amount = parse_amount(inp.get('amount'))
    cur = parse_currency(inp.get('currency'))
    d = inp.get('date')
    if d is not None:
        if not isinstance(d, str):
            raise ValueError('date must be a string DD.MM.YYYY')
        d = d.strip() or None
    if d:
        try:
            datetime.strptime(d, '%d.%m.%Y')
        except ValueError:
            raise ValueError('date must be formatted DD.MM.YYYY')
    iso, rows = fetch(d, cache)
    for line in rows:
        p = line.split('|')
        if len(p) == 5 and p[3] == cur:
            unit = float(p[2].replace(',', '.'))
            rate = float(p[4].replace(',', '.'))
            czk = round(amount * rate / unit, 2)
            return {'amount': amount, 'currency': cur, 'rate': rate, 'unit_amount': unit, 'czk': czk, 'rate_date': iso}
    if cur == 'CZK':
        return {'amount': amount, 'currency': cur, 'rate': 1.0, 'unit_amount': 1.0, 'czk': float(amount), 'rate_date': iso}
    raise ValueError(f'currency {cur} not found in CNB rate list')


def run(inp):
    cache = {}
    if isinstance(inp, list):
        return [single(x, cache) for x in inp]
    if isinstance(inp, dict) and isinstance(inp.get('batch'), list):
        return [single(x, cache) for x in inp['batch']]
    return single(inp, cache)

