import os, re


def _num(s):
    s = s.replace('\u00a0', ' ').strip()
    s = re.sub(r'[^\d,.\-\s]', '', s).strip()
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    s = s.replace(' ', '')
    try:
        return float(s)
    except ValueError:
        return None


def _date(s):
    s = s.strip()
    m = re.match(r'(\d{1,2})\.(\d{1,2})\.(\d{4})', s)
    if m:
        return '%s-%02d-%02d' % (m.group(3), int(m.group(2)), int(m.group(1)))
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})', s)
    return m.group(0) if m else None


def _field(text, pats):
    for p in pats:
        m = re.search(p, text, re.I | re.M)
        if m:
            return m.group(1).strip()
    return None


def _parse(text, name):
    lines = [l.rstrip() for l in text.splitlines()]
    supplier = None
    for l in lines:
        l2 = l.strip()
        if not l2 or re.match(r'(upom|invoice$|faktura)', l2, re.I) or 'znovu' in l2.lower():
            continue
        supplier = l2.split(',')[0].strip()
        break
    number = _field(text, [r'Invoice number:\s*(\S+)', r'FAKTURA[^\n]*?č\.\s*(\S+)'])
    vs = _field(text, [r'Variabilní symbol:\s*(\S+)', r'Variable symbol:\s*(\S+)'])
    if not vs and number:
        vs = re.sub(r'\D', '', number) or None
    date = _date(_field(text, [r'Datum vystavení:\s*(.+)', r'Invoice date:\s*(.+)']) or '')
    due = _date(_field(text, [r'Datum splatnosti:\s*(.+)', r'Payment due:\s*(.+)']) or '')
    po = _field(text, [r'Číslo objednávky:\s*(\S+)', r'PO reference:\s*(\S+)'])
    if po in ('-', ''):
        po = None
    total = _num(_field(text, [r'CELKEM K ÚHRADĚ:\s*(.+)', r'Total due:\s*(.+)']) or '')
    items = []
    for l in lines:
        if '|' in l:
            p = [x.strip() for x in l.split('|')]
            if len(p) >= 5 and _num(p[2]) is not None and re.search(r'\d', p[4]) and not p[0].lower().startswith('sku'):
                items.append({'code': p[0], 'description': p[1], 'qty': _num(p[2]), 'unit_price': _num(p[3]), 'amount': _num(p[4])})
            continue
        m = re.match(r'^(\S+)\s{2,}(.+?)\s{2,}(\d+(?:[,.]\d+)?)\s*(?:ks)?\s+(\d[\d ]*,\d{2})\s+(\d[\d ]*,\d{2})\s*$', l)
        if m:
            items.append({'code': m.group(1), 'description': m.group(2).strip(), 'qty': _num(m.group(3)), 'unit_price': _num(m.group(4)), 'amount': _num(m.group(5))})
    return {'file': name, 'supplier': supplier, 'invoice_number': number, 'vs': vs, 'date': date, 'due_date': due, 'po_number': po, 'items': items, 'total': total, 'resent': bool(re.search(r'upomínka|znovu|resent|reminder', text, re.I))}


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder'].strip():
        raise ValueError('folder (string) is required')
    d = os.path.join('inbox', inp['folder'], 'invoices')
    if not os.path.isdir(d):
        raise ValueError('invoices folder not found: ' + d)
    out, errors = [], []
    for root, _, files in sorted(os.walk(d)):
        for f in sorted(files):
            if not f.lower().endswith('.txt'):
                continue
            p = os.path.join(root, f)
            try:
                with open(p, encoding='utf-8', errors='replace') as fh:
                    rec = _parse(fh.read(), os.path.relpath(p, d))
                if not rec['invoice_number'] and not rec['total']:
                    errors.append({'file': f, 'error': 'no invoice data found'})
                    continue
                out.append(rec)
            except Exception as e:
                errors.append({'file': f, 'error': str(e)})
    return {'invoices': out, 'errors': errors}

import csv, os, re
from collections import defaultdict

def _num(s):
    if s is None: return None
    if isinstance(s,(int,float)): return float(s)
    t=re.sub(r'[\s\u00a0]','',str(s)).replace(',','.')
    try: return float(t)
    except ValueError: return None

def _date(s):
    m=re.match(r'(\d{1,2})\.(\d{1,2})\.(\d{4})',(s or '').strip())
    if m: return '%s-%02d-%02d'%(m.group(3),int(m.group(2)),int(m.group(1)))
    return (s or '').strip()

def _rows(path,errs):
    try:
        txt=open(path,encoding='utf-8-sig').read()
    except Exception as e:
        errs.append('%s: %s'%(os.path.basename(path),e)); return []
    first=txt.split('\n',1)[0]
    d=';' if first.count(';')>first.count(',') else ','
    return list(csv.DictReader(txt.splitlines(),delimiter=d))

def _w(s):
    s=re.sub(r'[^a-z0-9 ]','',(s or '').lower())
    return s.split()[0] if s.split() else ''

ALL=['duplicates','price_mismatch','quantity_mismatch','no_order','double_payment']

def run(inp):
    if not isinstance(inp,dict): raise ValueError('input must be an object')
    folder=inp.get('folder'); invs=inp.get('invoices')
    if not folder or not isinstance(folder,str): raise ValueError('folder is required')
    if not isinstance(invs,list): raise ValueError('invoices must be a list')
    checks=inp.get('checks') or ALL
    sf=(inp.get('supplier_filter') or '').strip().lower()
    base=os.path.join('inbox',folder)
    if not os.path.isdir(base): raise ValueError('folder not found: '+folder)
    errs=[]
    pos=defaultdict(dict)
    for r in _rows(os.path.join(base,'purchase_orders.csv'),errs):
        k=(r.get('po_number') or '').strip()
        if not k: continue
        sku=(r.get('sku') or '').strip()
        e=pos[k].setdefault(sku,{'qty':0.0,'price':_num(r.get('unit_price_czk'))})
        e['qty']+=_num(r.get('qty')) or 0
    bank=[]
    for r in _rows(os.path.join(base,'bank_statement.csv'),errs):
        a=_num(r.get('Částka'))
        if a is None: continue
        bank.append({'date':_date(r.get('Datum')),'amount':a,'party':r.get('Protistrana') or '','vs':(r.get('VS') or '').strip()})
    F=[]
    def add(t,i,**k):
        d={'type':t,'file':i.get('file') or '','invoice_number':str(i.get('invoice_number') or ''),'po_number':str(i.get('po_number') or ''),'bank_dates':[]}
        d.update(k); F.append(d)
    invs=[i for i in invs if isinstance(i,dict) and (not sf or sf in str(i.get('supplier') or '').lower())]
    groups=defaultdict(list)
    for i in invs: groups[(i.get('supplier') or '',i.get('invoice_number') or i.get('file'))].append(i)
    for g in groups.values():
        if len(g)>1 and 'duplicates' in checks:
            for i in g[1:]:
                add('duplicate',i,expected_amount=_num(g[0].get('total')) or 0,actual_amount=_num(i.get('total')) or 0,detail='Invoice appears %d times (files: %s)%s'%(len(g),', '.join(str(x.get('file')) for x in g),'; marked resent' if i.get('resent') else ''))
    for g in groups.values():
        i=next((x for x in g if not x.get('resent')),g[0])
        po=str(i.get('po_number') or '').strip()
        if po in ('-','—','none','None'): po=''
        if not po or po not in pos:
            if 'no_order' in checks:
                add('no_order',i,actual_amount=_num(i.get('total')) or 0,detail='No PO number on invoice' if not po else 'PO %s not found in purchase_orders.csv'%po)
        else:
            for it in i.get('items') or []:
                p=pos[po].get((it.get('code') or '').strip())
                if p is None:
                    if 'quantity_mismatch' in checks:
                        add('quantity_mismatch',i,actual_amount=_num(it.get('qty')) or 0,expected_amount=0,detail='Item %s not on PO %s'%(it.get('code'),po))
                    continue
                up=_num(it.get('unit_price')); q=_num(it.get('qty'))
                if 'price_mismatch' in checks and up is not None and p['price'] is not None and abs(up-p['price'])>0.005:
                    add('price_mismatch',i,expected_amount=p['price'],actual_amount=up,detail='Item %s unit price %s vs PO %s'%(it.get('code'),up,p['price']))
                if 'quantity_mismatch' in checks and q is not None and abs(q-p['qty'])>1e-9:
                    add('quantity_mismatch',i,expected_amount=p['qty'],actual_amount=q,detail='Item %s qty %s vs PO %s'%(it.get('code'),q,p['qty']))
        vs=str(i.get('vs') or '').strip()
        if vs and 'double_payment' in checks:
            m=[b for b in bank if b['vs']==vs and b['amount']<0]
            w=_w(i.get('supplier'))
            m2=[b for b in m if _w(b['party'])==w]
            m=m2 or m
            if len(m)>1:
                add('double_payment',i,expected_amount=_num(i.get('total')) or 0,actual_amount=round(-sum(b['amount'] for b in m),2),bank_dates=[b['date'] for b in m],detail='%d bank payments with VS %s'%(len(m),vs))
    summary={'invoices_checked':len(groups),'findings_total':len(F),'by_type':{},'bank_rows':len(bank),'po_count':len(pos),'errors':errs}
    for f in F: summary['by_type'][f['type']]=summary['by_type'].get(f['type'],0)+1
    return {'findings':F,'summary':summary}

