import csv, io, os, re
from pathlib import Path

ALL = ['duplicate', 'price_mismatch', 'quantity_mismatch', 'no_order', 'double_payment', 'payment_mismatch']

def num(s):
    if s is None: return None
    s = str(s).replace('\xa0', '').replace(' ', '').replace('\u202f', '')
    if not s: return None
    if ',' in s: s = s.replace('.', '').replace(',', '.')
    try: return float(s)
    except ValueError: return None

def iso(d):
    d = (d or '').strip()
    m = re.match(r'^(\d{1,2})\.(\d{1,2})\.(\d{4})$', d)
    return f'{m[3]}-{int(m[2]):02d}-{int(m[1]):02d}' if m else d

def read_csv(p):
    txt = Path(p).read_text(encoding='utf-8-sig')
    first = txt.splitlines()[0] if txt.strip() else ''
    dl = ';' if first.count(';') > first.count(',') else ','
    rows = list(csv.DictReader(io.StringIO(txt), delimiter=dl))
    return [{(k or '').strip().lower(): (v or '').strip() for k, v in r.items()} for r in rows]

def pick(r, *names):
    for n in names:
        if n in r: return r[n]
    return ''

def norm_vs(v): return re.sub(r'\D', '', str(v or '')).lstrip('0')

def r2(x): return round(x + 0.0, 2)

def run(inp):
    if not isinstance(inp, dict): raise ValueError('input must be an object')
    folder = inp.get('folder'); invs = inp.get('invoices')
    if not folder or not isinstance(folder, str): raise ValueError('folder is required')
