    if not rows:
        return []
    heads = [_norm(h) for h in rows[0]]
    return [dict(zip(heads, r)) for r in rows[1:]]


def _pick(row, names):
    for n in names:
        if n in row:
            return row[n].strip()
    return ''


def run(inp):
