    for k in ('supplier_invoices', 'customer_invoices', 'bank_transactions'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    if not inp.get('as_of_date') or not inp.get('target_month'):
        raise ValueError('as_of_date and target_month are required')
    asof = _d(inp['as_of_date'], 'as_of_date')
    tm = str(inp['target_month'])
    if not re.fullmatch(r'\d{4}-\d{2}', tm) or not 1 <= int(tm[5:]) <= 12:
        raise ValueError('target_month must be YYYY-MM')
    warnings = []
    known = []
    ignored = 0
    for i, b in enumerate(inp['bank_transactions']):
        try:
            dt = _d(b.get('date'), 'date')
            amt = _num(b.get('amount'))
            if amt is None:
                raise ValueError('amount')
        except Exception:
            warnings.append(f'bank_transactions[{i}] unparseable, skipped')
            continue
        if dt <= asof:
            known.append((dt, i, amt, b))
        else:
            ignored += 1
    known.sort(key=lambda x: (x[0], x[1]))
    if ignored:
        warnings.append(f'{ignored} bank rows dated after as_of_date ignored (not known)')
    pay_in = defaultdict(list)
    pay_out = defaultdict(list)
    for dt, i, amt, b in known:
        v = _vs(b.get('variable_symbol'))
        if v:
            (pay_in if amt > 0 else pay_out)[v].append((dt, i, amt))
    used = set()
    for v, l in list(pay_in.items()) + list(pay_out.items()):
        pass
    cust_vs = {_vs(c.get('variable_symbol')) for c in inp['customer_invoices']}
    sup_vs = {_vs(s.get('vs')) for s in inp['supplier_invoices']}
    for name, dic, vss in (('incoming', pay_in, cust_vs), ('outgoing', pay_out, sup_vs)):
        for v, l in dic.items():
            if v in vss:
                used.update(i for _, i, _ in l)
                seen = defaultdict(list)
                for dt, i, a in l:
                    seen[round(a, 2)].append(i)
                for a, ids in seen.items():
                    if len(ids) > 1:
                        warnings.append(f'possible duplicate {name} payment VS {v} amount {a} bank rows {ids}')
    overdue, inflows, outflows = [], [], []
    for c in inp['customer_invoices']:
        try:
            due = _d(c.get('due_date'), 'due_date')
        except ValueError:
            warnings.append(f"customer invoice {c.get('invoice_number')} bad due_date, skipped")
            continue
        amt = _num(c.get('amount_czk'))
        v = _vs(c.get('variable_symbol'))
        pays = pay_in.get(v, []) if v else []
        if pays:
            paid = sum(p[2] for p in pays)
            if amt is not None and abs(paid - amt) > 0.01:
                warnings.append(f"customer invoice {c.get('invoice_number')} paid {paid} differs from {amt}")
            continue
        rec = {'ref': c.get('invoice_number'), 'party': c.get('customer'), 'variable_symbol': c.get('variable_symbol'), 'due_date': str(due), 'amount': amt, 'estimate': True}
        if due < asof:
            rec['days_overdue'] = (asof - due).days
            overdue.append(rec)
        if str(due)[:7] == tm:
            inflows.append(dict(rec, type='customer_invoice_due'))
    for s in inp['supplier_invoices']:
        try:
            due = _d(s.get('due_date'), 'due_date')
        except ValueError:
            warnings.append(f"supplier invoice {s.get('invoice_number')} bad due_date, skipped")
            continue
        amt = _num(s.get('total'))
        v = _vs(s.get('vs'))
        if not s.get('po_number'):
            warnings.append(f"supplier invoice {s.get('invoice_number')} ({s.get('supplier')}) has no PO")
        if s.get('resent'):
            warnings.append(f"supplier invoice {s.get('invoice_number')} marked resent, possible duplicate")
        if v and pay_out.get(v):
            continue
        rec = {'ref': s.get('invoice_number'), 'party': s.get('supplier'), 'variable_symbol': s.get('vs'), 'due_date': str(due), 'amount': -abs(amt) if amt is not None else None, 'po_number': s.get('po_number'), 'estimate': True}
        if str(due)[:7] == tm:
            outflows.append(dict(rec, type='supplier_invoice_due'))
        elif due < date(int(tm[:4]), int(tm[5:]), 1):
            warnings.append(f"unpaid supplier invoice {s.get('invoice_number')} due {due} before target month, not included in outflows (amount {amt})")
    ninv = defaultdict(int)
    sk = defaultdict(int)
    for s in inp['supplier_invoices']:
        sk[str(s.get('invoice_number'))] += 1
    for k, n in sk.items():
        if n > 1:
            warnings.append(f'supplier invoice number {k} appears {n} times, possible duplicate')
    groups = defaultdict(list)
    for dt, i, amt, b in known:
        if amt < 0 and i not in used:
            groups[(str(b.get('counterparty') or '').strip().lower(), _vs(b.get('variable_symbol')))].append((dt, i, amt, b))
    for key, l in groups.items():
        months = {x[0].strftime('%Y-%m') for x in l}
        if len(months) < 2 or tm in months:
            continue
        dt, i, amt, b = l[-1]
        day = min(dt.day, 28)
        outflows.append({'ref': f'bank_transactions[{i}]', 'party': b.get('counterparty'), 'message': b.get('message'), 'due_date': f'{tm}-{day:02d}', 'amount': amt, 'type': 'recurring_bank_item', 'estimate': True})
    inf = sum(r['amount'] or 0 for r in inflows)
    outf = sum(r['amount'] or 0 for r in outflows)
    net = round(inf + outf, 2)
    bal = None
    for dt, i, amt, b in known:
        if _num(b.get('balance')) is not None:
            bal = _num(b.get('balance'))
    if bal is None:
        warnings.append('no known bank balance; closing balance assumes 0 opening')
        bal = 0.0
    closing = round(bal + net, 2)
    od = round(sum(r['amount'] or 0 for r in overdue), 2)
    summary = (f'ESTIMATE for {tm} as of {asof}: opening balance {bal}, inflows {round(inf,2)}, outflows {round(outf,2)}, '
               f'net {net}, closing {closing}. Overdue receivables ({len(overdue)}) total {od}, not included in inflows.')
    return {'overdue_receivables': overdue, 'expected_inflows': inflows, 'expected_outflows': outflows, 'net_exposure_estimate': net, 'closing_balance_estimate': closing, 'warnings': warnings, 'summary': summary}

import re
from datetime import date, datetime
import calendar

def _d(s, name):
    try:
        return datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
    except Exception:
        raise ValueError(f'{name} must be YYYY-MM-DD, got {s!r}')

def _vs(v):
    if v is None:
        return ''
    return re.sub(r'\D', '', str(v)).lstrip('0')

def _num(v):
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).replace(' ', '').replace('\xa0', '').replace(',', '.'))
    except Exception:
        return None

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'customer_invoices', 'bank_transactions'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    asof = _d(inp.get('as_of_date'), 'as_of_date')
    tm = str(inp.get('target_month') or '')
    if not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', tm):
        raise ValueError('target_month must be YYYY-MM')
    y, m = int(tm[:4]), int(tm[5:])
    mend = date(y, m, calendar.monthrange(y, m)[1])
    warnings = []
    bank = []
    for i, b in enumerate(inp['bank_transactions']):
        try:
            bd = _d(b.get('date'), 'date'); amt = _num(b.get('amount'))
            if amt is None:
                raise ValueError('amount')
            bank.append((bd, i, amt, b))
        except Exception:
            warnings.append(f'bank row {i} unparseable, skipped')
    later = [x for x in bank if x[0] > asof]
    if later:
        warnings.append(f'{len(later)} bank rows after as_of_date ignored')
    known = sorted([x for x in bank if x[0] <= asof], key=lambda x: (x[0], x[1]))
    opening = 0.0
    if known:
        bal = _num(known[-1][3].get('balance'))
        opening = bal if bal is not None else sum(x[2] for x in known)
    else:
        warnings.append('no bank rows on or before as_of_date; opening balance 0')
    inpaid, outpaid = {}, {}
    for bd, i, amt, b in known:
        v = _vs(b.get('variable_symbol'))
        if not v:
            continue
        if amt > 0:
            inpaid[v] = inpaid.get(v, 0) + amt
        else:
            outpaid[v] = outpaid.get(v, 0) + (-amt)

    def process(items, kind):
        res = []
        paid = inpaid if kind == 'r' else outpaid
        used = {}
        for inv in items:
            if kind == 'r':
                num = inv.get('invoice_number'); who = inv.get('customer')
                iss = inv.get('issue_date'); tot = _num(inv.get('amount_czk')); v = _vs(inv.get('variable_symbol'))
            else:
                num = inv.get('invoice_number'); who = inv.get('supplier')
                iss = inv.get('date'); tot = _num(inv.get('total')); v = _vs(inv.get('vs'))
            try:
                due = _d(inv.get('due_date'), 'due'); isd = _d(iss, 'issue')
            except ValueError:
                warnings.append(f'invoice {num} has bad dates, skipped'); continue
            if tot is None:
                warnings.append(f'invoice {num} has bad amount, skipped'); continue
            if isd > asof:
                warnings.append(f'invoice {num} issued {isd} after as_of_date, not counted')
                continue
            avail = paid.get(v, 0) - used.get(v, 0) if v else 0
            if v and avail >= tot - 0.01:
                used[v] = used.get(v, 0) + tot; continue
            part = max(avail, 0) if v else 0
            if part:
                used[v] = used.get(v, 0) + part
            if not v:
                warnings.append(f'invoice {num} has no VS, treated as unpaid')
            res.append({'invoice_number': num, 'counterparty': who, 'variable_symbol': v, 'due_date': str(due),
                        'amount': round(tot - part, 2), 'overdue': due < asof,
                        'days_overdue': (asof - due).days if due < asof else 0,
                        'due_in_target_month_or_before': due <= mend})
        return res

    rec = process(inp['customer_invoices'], 'r')
    pay = process(inp['supplier_invoices'], 'p')
    ov_r = [x for x in rec if x['overdue']]
    ov_p = [x for x in pay if x['overdue']]
    inflows = [x for x in rec if x['due_in_target_month_or_before']]
    outflows = [x for x in pay if x['due_in_target_month_or_before']]
    for x in rec + pay:
        if not x['due_in_target_month_or_before']:
            warnings.append(f"{x['invoice_number']} unpaid but due {x['due_date']} after target month, excluded")
    si = sum(x['amount'] for x in inflows); so = sum(x['amount'] for x in outflows)
    ovr = sum(x['amount'] for x in ov_r)
    net = round(si - so, 2)
    closing = round(opening + net, 2)
    sc = {
        'optimistic': round(opening + si - so, 2),
        'base_overdue_receivables_50pct': round(opening + si - ovr * 0.5 - so, 2),
        'pessimistic_no_overdue_receivables': round(opening + si - ovr - so, 2)}
    warnings.append('recurring items (rent, payroll) not forecast; only listed invoices included')
    summ = (f'As of {asof}, opening balance {opening:.2f}. Expected inflows {si:.2f} ({len(inflows)} invoices, '
            f'{len(ov_r)} overdue), outflows {so:.2f} ({len(outflows)} invoices, {len(ov_p)} overdue). '
            f'Net {net:.2f}, closing estimate {closing:.2f} for {tm}.')
    return {'opening_balance': round(opening, 2), 'overdue_receivables': ov_r, 'overdue_payables': ov_p,
            'expected_inflows': inflows, 'expected_outflows': outflows, 'net_exposure_estimate': net,
            'closing_balance_estimate': closing, 'scenarios': sc, 'warnings': warnings, 'summary': summ}

import os, re, zipfile, datetime
import xml.etree.ElementTree as ET

HEADS = {
    'skills': ['skills', 'technical skills', 'core competencies', 'key skills', 'competencies', 'technologies'],
    'experience': ['experience', 'work experience', 'professional experience', 'employment', 'employment history', 'work history', 'career history'],
    'education': ['education', 'academic background', 'qualifications', 'education and training'],
    'certifications': ['certifications', 'certificates', 'certification', 'licenses', 'licenses and certifications', 'courses'],
}
MON = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}
TOK = r'(?:[A-Za-z]{3,9}\.?\s+)?\d{4}'
RNG = re.compile('(' + TOK + r')\s*(?:-|\u2013|\u2014|to)\s*(' + TOK + r'|present|current|now|today)', re.I)


def _pt(s):
    s = s.strip().lower()
    if s in ('present', 'current', 'now', 'today'):
        t = datetime.date.today()
        return t.year * 12 + t.month - 1
    y = int(re.search(r'\d{4}', s).group())
    m = re.match(r'[a-z]{3}', s)
    mo = MON.get(m.group(), 1) if m else 1
    return y * 12 + mo - 1


def _docx(p):
    ns = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    with zipfile.ZipFile(p) as z:
        root = ET.fromstring(z.read('word/document.xml'))
    out = []
    for para in root.iter(ns + 'p'):
        out.append(''.join(t.text or '' for t in para.iter(ns + 't')))
    return '\n'.join(out)


def _pdf(p):
    from pypdf import PdfReader
    return '\n'.join((pg.extract_text() or '') for pg in PdfReader(p).pages)


def _text(p):
    e = p.lower().rsplit('.', 1)[-1]
    if e == 'txt':
        return open(p, encoding='utf-8', errors='replace').read()
    if e == 'docx':
        return _docx(p)
    if e == 'pdf':
        return _pdf(p)
    return None


def _head(line):
    k = re.sub(r'[^a-z& ]', '', line.lower()).replace('&', 'and').strip()
    if len(line) > 40:
        return None
    for sec, names in HEADS.items():
        if k in names:
            return sec
    return None


def _items(lines):
    out = []
    for l in lines:
        l = re.sub(r'^[\s\-\*\u2022\u00b7\u25aa>]+', '', l).strip()
        if l:
            out.append(l)
    return out


def _skills(lines):
    res = []
    for l in _items(lines):
        if ':' in l:
            l = l.split(':', 1)[1]
        for s in re.split(r'[,;|\u2022]', l):
            s = s.strip(' .')
            if s and s not in res:
                res.append(s)
    return res


def _exp(lines):
    ents = []
    cur = None
    for l in _items(lines):
        m = RNG.search(l)
        if m:
            try:
                a, b = _pt(m.group(1)), _pt(m.group(2))
            except Exception:
                a = b = None
            cur = {'title': RNG.sub('', l).strip(' ,-|()'), 'start': m.group(1).strip(), 'end': m.group(2).strip(), 'details': [], '_iv': (a, b)}
            ents.append(cur)
        elif cur is not None:
            cur['details'].append(l)
        else:
            cur = {'title': l, 'start': None, 'end': None, 'details': [], '_iv': None}
            ents.append(cur)
    return ents


def _years(ents, text):
    iv = sorted(e['_iv'] for e in ents if e.get('_iv') and e['_iv'][0] is not None and e['_iv'][1] >= e['_iv'][0])
    if iv:
        tot = 0
        cs, ce = iv[0]
        for s, e in iv[1:]:
            if s <= ce:
                ce = max(ce, e)
            else:
                tot += ce - cs
                cs, ce = s, e
        tot += ce - cs
        return round(tot / 12, 1)
    ys = [int(x) for x in re.findall(r'(\d{1,2})\s*\+?\s*years', text, re.I)]
    return float(max(ys)) if ys else 0.0


def _parse(text):
    secs = {k: [] for k in HEADS}
    cur = None
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        h = _head(s.rstrip(':'))
        if h:
            cur = h
            continue
        if cur:
            secs[cur].append(s)
    ents = _exp(secs['experience'])
    yrs = _years(ents, text)
    for e in ents:
        e.pop('_iv', None)
    return {
        'skills': _skills(secs['skills']),
        'experience': ents,
        'education': _items(secs['education']),
        'certifications': _items(secs['certifications']),
        'years_experience': yrs,
    }


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder'].strip():
        raise ValueError('input must be a dict with a non-empty string field folder')
    base = os.path.join('.', 'inbox', inp['folder'])
    if '..' in inp['folder'].replace('\\', '/').split('/'):
        raise ValueError('invalid folder')
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    cvs, errors = [], []
    for r, _, fs in os.walk(base):
        for n in sorted(fs):
            p = os.path.join(r, n)
            rel = os.path.relpath(p, base)
            if n.lower().rsplit('.', 1)[-1] not in ('txt', 'pdf', 'docx'):
                errors.append({'file': rel, 'error': 'unsupported file type'})
                continue
            try:
                t = _text(p)
                if not t or not t.strip():
                    errors.append({'file': rel, 'error': 'no text extracted'})
                    continue
                d = _parse(t)
                d['file'] = rel
                cvs.append(d)
            except Exception as ex:
                errors.append({'file': rel, 'error': str(ex)[:200]})
    cvs.sort(key=lambda c: c['file'])
    return {'cvs': cvs, 'errors': errors}

import os, re, zipfile, datetime
from xml.etree import ElementTree as ET

EXTS = ('.txt', '.md', '.pdf', '.docx')
ALIASES = {
    'skills': ['skills', 'technical skills', 'key skills', 'core skills', 'core competencies', 'competencies', 'technologies', 'tech stack', 'skills summary'],
    'experience': ['experience', 'work experience', 'professional experience', 'employment', 'employment history', 'work history', 'career history', 'relevant experience'],
    'education': ['education', 'academic background', 'academic qualifications', 'education and training', 'qualifications'],
    'certifications': ['certifications', 'certificates', 'certification', 'licenses', 'licenses and certifications', 'courses', 'training', 'training and certifications'],
    'summary': ['summary', 'profile', 'professional summary', 'about me', 'objective', 'about'],
    'languages': ['languages'],
    'projects': ['projects', 'personal projects'],
    'interests': ['interests', 'hobbies'],
}
HEAD = {a: k for k, v in ALIASES.items() for a in v}
MON = {m: i + 1 for i, m in enumerate(['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}
DT = r'(?:(?:[A-Za-z]{3,9})\.?\s+\d{4}|\d{1,2}[/.]\d{4}|\d{4})'
RANGE = re.compile('(' + DT + r')\s*(?:-|\u2013|\u2014|to)\s*(' + DT + r'|present|current|now|today|ongoing)', re.I)


def read_docx(p):
    with zipfile.ZipFile(p) as z:
        root = ET.fromstring(z.read('word/document.xml'))
    ns = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    lines = []
    for para in root.iter(ns + 'p'):
        t = ''.join((n.text or '') if n.tag == ns + 't' else ('\t' if n.tag == ns + 'tab' else '') for n in para.iter() if n.tag in (ns + 't', ns + 'tab'))
        lines.append(t)
    return '\n'.join(lines)


def read_pdf(p):
    from pypdf import PdfReader
    return '\n'.join((pg.extract_text() or '') for pg in PdfReader(p).pages)


def read_file(p):
    l = p.lower()
    if l.endswith('.docx'):
        return read_docx(p)
    if l.endswith('.pdf'):
        return read_pdf(p)
    return open(p, encoding='utf-8', errors='replace').read()


def heading(line):
    s = re.sub(r'^[#*\s_=\-]+|[*:\s_=\-]+$', '', line.strip()).lower()
    s = s.replace('&', 'and')
    if 0 < len(s) <= 40:
        return HEAD.get(s)
    return None


def split_sections(text):
    secs, cur, order = {}, 'header', ['header']
    secs['header'] = []
    for line in text.splitlines():
        h = heading(line)
        if h:
            cur = h
            if cur not in secs:
                secs[cur] = []
                order.append(cur)
            continue
        secs[cur].append(line)
    return secs, order


def pdate(s, end):
    s = s.strip().lower()
    if s in ('present', 'current', 'now', 'today', 'ongoing'):
        t = datetime.date.today()
        return t.year, t.month
    m = re.match(r'([a-z]{3,9})\.?\s+(\d{4})', s)
    if m and m.group(1)[:3] in MON:
        return int(m.group(2)), MON[m.group(1)[:3]]
    m = re.match(r'(\d{1,2})[/.](\d{4})', s)
    if m and 1 <= int(m.group(1)) <= 12:
        return int(m.group(2)), int(m.group(1))
    m = re.match(r'(\d{4})$', s)
    if m:
        return int(m.group(1)), 12 if end else 1
    return None


def clean_bullet(l):
    return re.sub(r'^\s*(?:[-*\u2022\u25cf\u25aa\u2013>]+|\d+[.)])\s*', '', l).strip()


def parse_experience(lines):
    entries, cur = [], None
    for raw in lines:
        if not raw.strip():
            continue
        m = RANGE.search(raw)
        is_bullet = bool(re.match(r'^\s*(?:[-*\u2022\u25cf\u25aa>]|\d+[.)])\s', raw))
        if m and not is_bullet:
            a, b = pdate(m.group(1), False), pdate(m.group(2), True)
            title = clean_bullet((raw[:m.start()] + ' ' + raw[m.end():])).strip(' ,|-\u2013()')
            cur = {'title': title, 'start': m.group(1), 'end': m.group(2), 'details': []}
            cur['_a'], cur['_b'] = a, b
            entries.append(cur)
        elif cur is None:
            cur = {'title': clean_bullet(raw), 'start': None, 'end': None, 'details': [], '_a': None, '_b': None}
            entries.append(cur)
        else:
            t = clean_bullet(raw)
            if not cur['title']:
                cur['title'] = t
            elif is_bullet or cur['details']:
                cur['details'].append(t)
            elif not cur.get('company'):
                cur['company'] = t
            else:
                cur['details'].append(t)
    return entries


def months_total(entries):
    iv = []
    for e in entries:
        a, b = e.get('_a'), e.get('_b')
        if a and b:
            x, y = a[0] * 12 + a[1], b[0] * 12 + b[1]
            if y >= x:
                iv.append((x, y + (0 if e['end'] and e['end'].isdigit() and len(e['end']) == 4 else 1) if False else y + 1))
    iv.sort()
    tot, ce = 0, None
    cs = None
    for s, e in iv:
        if cs is None:
            cs, ce = s, e
        elif s <= ce:
            ce = max(ce, e)
        else:
            tot += ce - cs
            cs, ce = s, e
    if cs is not None:
        tot += ce - cs
    return tot


def parse_skills(lines):
    out, seen = [], set()
    for l in lines:
        l = clean_bullet(l)
        if not l:
            continue
        if ':' in l and len(l.split(':', 1)[0]) <= 30:
            l = l.split(':', 1)[1]
        for p in re.split(r'[,;|\u2022\u00b7/]\s*|\s{3,}', l):
            p = p.strip(' .')
            if p and len(p) <= 60 and p.lower() not in seen:
                seen.add(p.lower())
                out.append(p)
    return out


def parse_education(lines):
    out = []
    for l in lines:
        t = clean_bullet(l)
        if not t:
            continue
        yrs = re.findall(r'\b(?:19|20)\d{2}\b', t)
        out.append({'text': t, 'years': yrs})
    return out


def parse_text(text, name):
    secs, order = split_sections(text)
    exp = parse_experience(secs.get('experience', []))
    months = months_total(exp)
    years = round(months / 12, 1) if months else None
    if years is None:
        m = re.search(r'(\d{1,2})\+?\s*(?:years|yrs)', text, re.I)
        years = float(m.group(1)) if m else 0.0
    for e in exp:
        e.pop('_a', None)
        e.pop('_b', None)
    return {
        'file': name,
        'skills': parse_skills(secs.get('skills', [])),
        'experience': exp,
        'education': parse_education(secs.get('education', [])),
        'certifications': [clean_bullet(l) for l in secs.get('certifications', []) if l.strip()],
        'years_experience': float(years),
        'sections': [s for s in order if s != 'header' and secs.get(s) is not None],
    }


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder'].strip():
        raise ValueError('input must be a dict with a non-empty string field "folder"')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    files = []
    for r, _, fs in os.walk(base):
        for n in sorted(fs):
            if n.lower().endswith(EXTS):
                files.append(os.path.join(r, n))
    files.sort()
    if not files:
        raise ValueError('no CV files (txt, md, pdf, docx) found in folder')
    parsed, errors = [], []
    for p in files:
        rel = os.path.relpath(p, base)
        try:
            text = read_file(p)
            if not text.strip():
                errors.append({'file': rel, 'error': 'no text extracted'})
                continue
            parsed.append(parse_text(text, rel))
        except Exception as e:
            errors.append({'file': rel, 'error': str(e)[:200]})
    res = {'cv': parsed[0] if parsed else {}, 'all_cvs': parsed, 'errors': errors}
    return res

import os, re, zipfile, datetime
from xml.etree import ElementTree as ET

EXTS = ('.txt', '.md', '.pdf', '.docx')
ALIASES = {
    'skills': ['skills', 'technical skills', 'key skills', 'core skills', 'core competencies', 'competencies', 'technologies', 'tech stack', 'skills summary'],
    'experience': ['experience', 'work experience', 'professional experience', 'employment', 'employment history', 'work history', 'career history', 'relevant experience'],
    'education': ['education', 'academic background', 'academic qualifications', 'education and training', 'qualifications'],
    'certifications': ['certifications', 'certificates', 'certification', 'licenses', 'licenses and certifications', 'courses', 'training', 'training and certifications'],
    'summary': ['summary', 'profile', 'professional summary', 'about me', 'objective', 'about'],
    'languages': ['languages'],
    'projects': ['projects', 'personal projects'],
    'interests': ['interests', 'hobbies'],
}
HEAD = {a: k for k, v in ALIASES.items() for a in v}
MON = {m: i + 1 for i, m in enumerate(['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}
MONRE = r'(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*'
DT = r'(?:' + MONRE + r'\.?\s+\d{4}|\d{1,2}[/.]\d{4}|\d{4})'
RANGE = re.compile(r'\b(' + DT + r')\s*(?:-|\u2013|\u2014|to)\s*(' + DT + r'|present|current|now|today|ongoing)', re.I)


def read_docx(p):
    with zipfile.ZipFile(p) as z:
        root = ET.fromstring(z.read('word/document.xml'))
    ns = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    lines = []
    for para in root.iter(ns + 'p'):
        t = ''.join((n.text or '') if n.tag == ns + 't' else '\t' for n in para.iter() if n.tag in (ns + 't', ns + 'tab'))
        lines.append(t)
    return '\n'.join(lines)


def read_pdf(p):
    from pypdf import PdfReader
    return '\n'.join((pg.extract_text() or '') for pg in PdfReader(p).pages)


def read_file(p):
    l = p.lower()
    if l.endswith('.docx'):
        return read_docx(p)
    if l.endswith('.pdf'):
        return read_pdf(p)
    return open(p, encoding='utf-8', errors='replace').read()


def heading(line):
    s = re.sub(r'^[#*\s_=\-]+|[*:\s_=\-]+$', '', line.strip()).lower()
    s = s.replace('&', 'and')
    if 0 < len(s) <= 40:
        return HEAD.get(s)
    return None


def split_sections(text):
    secs, cur, order = {'header': []}, 'header', ['header']
    for line in text.splitlines():
        h = heading(line)
        if h:
            cur = h
            if cur not in secs:
                secs[cur] = []
                order.append(cur)
            continue
        secs[cur].append(line)
    return secs, order


def pdate(s, end):
    s = s.strip().lower()
    if s in ('present', 'current', 'now', 'today', 'ongoing'):
        t = datetime.date.today()
        return t.year, t.month
    m = re.match(r'([a-z]{3,9})\.?\s+(\d{4})', s)
    if m and m.group(1)[:3] in MON:
        return int(m.group(2)), MON[m.group(1)[:3]]
    m = re.match(r'(\d{1,2})[/.](\d{4})', s)
    if m and 1 <= int(m.group(1)) <= 12:
        return int(m.group(2)), int(m.group(1))
    m = re.match(r'(\d{4})$', s)
    if m:
        return int(m.group(1)), 12 if end else 1
    return None


def clean_bullet(l):
    return re.sub(r'^\s*(?:[-*\u2022\u25cf\u25aa\u2013>]+|\d+[.)])\s*', '', l).strip()


def parse_experience(lines):
    entries, cur = [], None
    for raw in lines:
        if not raw.strip():
            continue
        m = RANGE.search(raw)
        is_bullet = bool(re.match(r'^\s*(?:[-*\u2022\u25cf\u25aa>]|\d+[.)])\s', raw))
        if m and not is_bullet:
            a, b = pdate(m.group(1), False), pdate(m.group(2), True)
            title = clean_bullet((raw[:m.start()] + ' ' + raw[m.end():])).strip(' ,|-\u2013()')
            cur = {'title': title, 'start': m.group(1), 'end': m.group(2), 'details': [], '_a': a, '_b': b}
            entries.append(cur)
        elif cur is None:
            cur = {'title': clean_bullet(raw), 'start': None, 'end': None, 'details': [], '_a': None, '_b': None}
            entries.append(cur)
        else:
            t = clean_bullet(raw)
            if not cur['title']:
                cur['title'] = t
            elif is_bullet or cur['details']:
                cur['details'].append(t)
            elif not cur.get('company'):
                cur['company'] = t
            else:
                cur['details'].append(t)
    return entries


def months_total(entries):
    iv = []
    for e in entries:
        a, b = e.get('_a'), e.get('_b')
        if a and b:
            x, y = a[0] * 12 + a[1], b[0] * 12 + b[1]
            if y >= x:
                iv.append((x, y + 1))
    iv.sort()
    tot, cs, ce = 0, None, None
    for s, e in iv:
        if cs is None:
            cs, ce = s, e
        elif s <= ce:
            ce = max(ce, e)
        else:
            tot += ce - cs
            cs, ce = s, e
    if cs is not None:
        tot += ce - cs
    return tot


def parse_skills(lines):
    out, seen = [], set()
    for l in lines:
        l = clean_bullet(l)
        if not l:
            continue
        if ':' in l and len(l.split(':', 1)[0]) <= 30:
