            p = p.strip(' .')
            if p and len(p) <= 60 and p.lower() not in seen:
                seen.add(p.lower())
                out.append(p)
    return out


def parse_education(lines):
    out = []
    for l in lines:
        t = clean_bullet(l)
        if not t:
            continue
        out.append({'text': t, 'years': re.findall(r'\b(?:19|20)\d{2}\b', t)})
    return out


def parse_text(text, name):
    secs, order = split_sections(text)
    exp = parse_experience(secs.get('experience', []))
    months = months_total(exp)
    years = round(months / 12, 1) if months else None
    if years is None:
        m = re.search(r'(\d{1,2})\+?\s*(?:years|yrs)', text, re.I)
        years = float(m.group(1)) if m else 0.0
    for e in exp:
        e.pop('_a', None)
        e.pop('_b', None)
    return {
        'file': name,
        'skills': parse_skills(secs.get('skills', [])),
        'experience': exp,
        'education': parse_education(secs.get('education', [])),
        'certifications': [clean_bullet(l) for l in secs.get('certifications', []) if l.strip()],
        'years_experience': float(years),
        'sections': [s for s in order if s != 'header'],
    }


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder'].strip():
        raise ValueError('input must be a dict with a non-empty string field "folder"')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    files = []
    for r, _, fs in os.walk(base):
        for n in fs:
            if n.lower().endswith(EXTS):
                files.append(os.path.join(r, n))
    files.sort()
    if not files:
        raise ValueError('no CV files (txt, md, pdf, docx) found in folder')
    parsed, errors = [], []
    for p in files:
