import csv, os, re
from datetime import datetime, date


def _num(s):
    s = (s or '').strip().replace('\xa0', '').replace(' ', '')
    if not s:
        return None
    if ',' in s:
        s = s.replace('.', '').replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return None


def _date(s):
    s = (s or '').strip()
    for f in ('%d.%m.%Y', '%Y-%m-%d', '%d. %m. %Y', '%d/%m/%Y'):
        try:
            return datetime.strptime(s, f).date().isoformat()
        except ValueError:
            pass
    return None


def _read(path):
    raw = open(path, 'rb').read()
    for enc in ('utf-8-sig', 'cp1250'):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    first = text.split('\n', 1)[0]
    delim = ';' if first.count(';') >= first.count(',') else ','
    return list(csv.DictReader(text.splitlines(), delimiter=delim))


def _digits(s):
    return re.sub(r'\D', '', s or '')


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('input must contain a non-empty string field folder')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    errors = []
    invoices = []
    txs = []
    p = os.path.join(base, 'customer_invoices.csv')
    if os.path.exists(p):
        try:
            for i, r in enumerate(_read(p), 2):
                try:
                    amt = _num(r.get('castka_kc'))
                    num = (r.get('cislo_faktury') or '').strip()
                    if not num or amt is None:
                        errors.append('customer_invoices row %d unparsable' % i)
                        continue
                    invoices.append({'invoice_number': num, 'customer': (r.get('odberatel') or '').strip(),
                                     'issue_date': _date(r.get('datum_vystaveni')),
                                     'due_date': _date(r.get('datum_splatnosti')),
                                     'amount_czk': amt, 'paid': False, 'paid_date': None, 'payment_index': None})
                except Exception as e:
                    errors.append('customer_invoices row %d: %s' % (i, e))
        except Exception as e:
            errors.append('customer_invoices.csv: %s' % e)
    p = os.path.join(base, 'bank_statement.csv')
    if os.path.exists(p):
        try:
            for i, r in enumerate(_read(p), 2):
                amt = _num(r.get('Částka'))
                d = _date(r.get('Datum'))
                if amt is None or d is None:
                    errors.append('bank_statement row %d unparsable' % i)
                    continue
                txs.append({'date': d, 'amount': amt, 'currency': (r.get('Měna') or '').strip(),
                            'counterparty': (r.get('Protistrana') or '').strip(),
                            'vs': (r.get('VS') or '').strip(), 'message': (r.get('Zpráva') or '').strip(),
                            'balance': _num(r.get('Zůstatek')), 'matched_invoice': None})
        except Exception as e:
            errors.append('bank_statement.csv: %s' % e)
    for k, t in enumerate(txs):
        if t['amount'] <= 0:
            continue
        vs = _digits(t['vs'])
        for inv in invoices:
            if inv['paid']:
                continue
            if vs and vs == _digits(inv['invoice_number']) and abs(inv['amount_czk'] - t['amount']) < 0.005:
                inv['paid'] = True
                inv['paid_date'] = t['date']
                inv['payment_index'] = k
                t['matched_invoice'] = inv['invoice_number']
                break
    return {'customer_invoices': invoices, 'bank_transactions': txs, 'errors': errors}

import re
from datetime import date, datetime
from collections import defaultdict


def _d(s, name):
    if s is None or s == '':
        return None
    try:
        return datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
    except ValueError:
        raise ValueError(f'{name} must be YYYY-MM-DD, got {s!r}')


def _num(v):
    if isinstance(v, (int, float)):
        return float(v)
    try:
        s = str(v).replace('\xa0', '').replace(' ', '').replace(',', '.')
        return float(s)
    except Exception:
        return None


def _ym(s):
    if not isinstance(s, str) or not re.fullmatch(r'\d{4}-\d{2}', s) or not 1 <= int(s[5:]) <= 12:
        raise ValueError('horizon_month must be YYYY-MM')
    return s


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'customer_invoices', 'bank_transactions'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    asof = _d(inp.get('as_of_date'), 'as_of_date') or date.today()
    hm = inp.get('horizon_month')
    hm = _ym(hm) if hm else asof.strftime('%Y-%m')
    hy, hmo = int(hm[:4]), int(hm[5:])
    skipped = []

    txs = []
    for i, t in enumerate(inp['bank_transactions']):
        try:
            a = _num(t.get('amount'))
            dt = _d(t.get('date'), 'date')
            if a is None or dt is None:
                raise ValueError('bad')
            txs.append((dt, a, t))
        except Exception:
            skipped.append(f'bank_transactions[{i}]')
    txs.sort(key=lambda x: x[0])
    opening = 0.0
    last = [x for x in txs if x[0] <= asof and _num(x[2].get('balance')) is not None]
    if last:
        opening = _num(last[-1][2]['balance'])
    opening_src = 'last bank balance on or before as_of_date' if last else 'no balance available, assumed 0'

    inflows, overdue = [], []
    for i, c in enumerate(inp['customer_invoices']):
        try:
            if c.get('paid'):
                continue
            amt = _num(c.get('amount_czk', c.get('amount')))
            due = _d(c.get('due_date'), 'due_date')
            if amt is None or due is None:
                raise ValueError('bad')
        except Exception:
            skipped.append(f'customer_invoices[{i}]')
            continue
        item = {'invoice_number': c.get('invoice_number'), 'customer': c.get('customer'), 'amount': amt, 'due_date': due.isoformat()}
        if due < asof:
            overdue.append({**item, 'days_overdue': (asof - due).days})
        if (due.year, due.month) == (hy, hmo) or due < asof:
            inflows.append({**item, 'type': 'open_receivable', 'estimate': True,
                            'note': 'overdue, collection timing uncertain' if due < asof else 'expected on due date'})
    overdue.sort(key=lambda x: -x['days_overdue'])

    outflows = []
    for i, s in enumerate(inp['supplier_invoices']):
        try:
            if s.get('paid'):
                continue
            amt = _num(s.get('total'))
            due = _d(s.get('due_date'), 'due_date')
            if amt is None or due is None:
                raise ValueError('bad')
        except Exception:
            skipped.append(f'supplier_invoices[{i}]')
            continue
        if (due.year, due.month) == (hy, hmo) or due < asof:
            outflows.append({'type': 'supplier_invoice', 'supplier': s.get('supplier'), 'invoice_number': s.get('invoice_number'),
                             'amount': amt, 'due_date': due.isoformat(), 'estimate': False,
                             'note': 'past due, unpaid' if due < asof else 'due in horizon month'})

    groups = defaultdict(list)
    for dt, a, t in txs:
        if a < 0 and not t.get('matched_invoice'):
            groups[(str(t.get('counterparty', '')).strip().lower(), round(a, 2))].append((dt, t))
    for (cp, a), lst in groups.items():
        months = {(d.year, d.month) for d, _ in lst}
        if len(months) >= 2:
            day = lst[-1][0].day
            outflows.append({'type': 'recurring_bank_item', 'counterparty': lst[-1][1].get('counterparty'),
                             'description': lst[-1][1].get('message'), 'amount': -a,
                             'expected_date': f'{hy:04d}-{hmo:02d}-{min(day, 28):02d}', 'estimate': True,
                             'note': f'recurring in {len(months)} months'})

    tin = sum(x['amount'] for x in inflows)
    tout = sum(x['amount'] for x in outflows)
    net = round(opening + tin - tout, 2)
    summary = (f'Horizon {hm}, as of {asof}: opening balance {opening:.2f} ({opening_src}); estimated inflows {tin:.2f}; '
               f'outflows {tout:.2f}; estimated closing exposure {net:.2f}; {len(overdue)} overdue receivable(s).')
    if skipped:
        summary += ' Could not parse: ' + ', '.join(skipped) + '.'
    return {'opening_balance': opening, 'expected_inflows': inflows, 'expected_outflows': outflows,
            'overdue_receivables': overdue, 'net_exposure_estimate': net, 'summary': summary,
            'unparsed': skipped}

import re
from datetime import date, datetime, timedelta
from calendar import monthrange

def _d(s):
    if isinstance(s, date):
        return s
    try:
        return datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
    except Exception:
        return None

def _n(s):
    return re.sub(r'[^a-z0-9]', '', str(s or '').lower())

def _vs(s):
    return re.sub(r'\D', '', str(s or '')).lstrip('0')

def _num(x):
    if isinstance(x, (int, float)):
        return float(x)
    try:
        return float(str(x).replace('\xa0', '').replace(' ', '').replace(',', '.'))
    except Exception:
        return None

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'customer_invoices', 'bank_transactions'):
        if not isinstance(inp.get(k), list):
            raise ValueError(k + ' must be a list')
    asof = _d(inp.get('as_of_date')) if inp.get('as_of_date') else date.today()
    if asof is None:
        raise ValueError('as_of_date must be YYYY-MM-DD')
    hm = inp.get('horizon_month')
    if hm:
        m = re.fullmatch(r'(\d{4})-(\d{2})', str(hm))
        if not m or not 1 <= int(m.group(2)) <= 12:
            raise ValueError('horizon_month must be YYYY-MM')
        hy, hmo = int(m.group(1)), int(m.group(2))
    else:
        nx = (asof.replace(day=1) + timedelta(days=32))
        hy, hmo = nx.year, nx.month
    hstart = date(hy, hmo, 1)
    hend = date(hy, hmo, monthrange(hy, hmo)[1])
    tol = float(inp.get('amount_tolerance', 1.0))
    bank = []
    for b in inp['bank_transactions']:
        if not isinstance(b, dict):
            continue
        a = _num(b.get('amount')); dt = _d(b.get('date'))
        if a is None or dt is None:
            continue
        bank.append(dict(b, _a=a, _dt=dt))
    opening = 0.0
    if bank:
        last = max(range(len(bank)), key=lambda i: (bank[i]['_dt'], i))
        bl = _num(bank[last].get('balance'))
        opening = round(bl if bl is not None else 0.0, 2)
    used = set()
    seen = {}
    dups = []
    uniq = []
    for inv in inp['supplier_invoices']:
        if not isinstance(inv, dict):
            continue
        key = (_n(inv.get('supplier')), _n(inv.get('invoice_number')))
        if key in seen:
            dups.append({'file': inv.get('file'), 'supplier': inv.get('supplier'), 'invoice_number': inv.get('invoice_number'), 'total': inv.get('total'), 'reason': 'duplicate of ' + str(uniq[seen[key]].get('file'))})
            continue
        seen[key] = len(uniq)
        uniq.append(inv)
    paid, outs, ins, overdue = [], [], [], []
    def match(ref_vs, ref_num, amt, sign):
        for i, b in enumerate(bank):
            if i in used or (b['_a'] < 0) != (sign < 0):
                continue
            bv = _vs(b.get('vs'))
            txt = _n(b.get('message'))
            ok = (ref_vs and bv == ref_vs) or (ref_num and len(ref_num) >= 4 and ref_num in txt)
            if ok and abs(abs(b['_a']) - amt) <= tol:
                used.add(i)
                return b
        return None
    for inv in uniq:
        tot = _num(inv.get('total'))
        if tot is None:
            dups.append({'file': inv.get('file'), 'reason': 'unparseable total'})
            continue
        b = match(_vs(inv.get('vs')), _n(inv.get('invoice_number')), tot, -1)
        if b:
            paid.append({'supplier': inv.get('supplier'), 'invoice_number': inv.get('invoice_number'), 'amount': tot, 'paid_date': str(b['_dt']), 'bank_vs': b.get('vs')})
            continue
        dd = _d(inv.get('due_date'))
        if dd is not None and dd > hend:
            continue
        outs.append({'type': 'supplier_invoice', 'supplier': inv.get('supplier'), 'invoice_number': inv.get('invoice_number'), 'due_date': str(dd) if dd else None, 'amount': round(tot, 2), 'overdue': bool(dd and dd < asof), 'days_overdue': (asof - dd).days if dd and dd < asof else 0})
    for c in inp['customer_invoices']:
        if not isinstance(c, dict):
            continue
        amt = _num(c.get('amount_czk', c.get('amount')))
        if amt is None or c.get('paid'):
            continue
        if match(_vs(c.get('invoice_number')), _n(c.get('invoice_number')), amt, 1):
            continue
        dd = _d(c.get('due_date'))
        if dd is not None and dd > hend:
            continue
        row = {'type': 'receivable', 'customer': c.get('customer'), 'invoice_number': c.get('invoice_number'), 'due_date': str(dd) if dd else None, 'amount': round(amt, 2), 'days_overdue': (asof - dd).days if dd and dd < asof else 0}
        ins.append(row)
        if row['days_overdue'] > 0:
            overdue.append(row)
    groups = {}
    for i, b in enumerate(bank):
        if b['_a'] < 0 and not b.get('matched_invoice') and i not in used:
            groups.setdefault((_n(b.get('counterparty')), _vs(b.get('vs'))), []).append(b)
    for g in groups.values():
        months = {(x['_dt'].year, x['_dt'].month) for x in g}
        if len(months) < 2 or (hy, hmo) in months:
            continue
        lt = max(g, key=lambda x: x['_dt'])
        day = min(lt['_dt'].day, hend.day)
        outs.append({'type': 'recurring', 'supplier': lt.get('counterparty'), 'invoice_number': None, 'description': lt.get('message'), 'due_date': str(date(hy, hmo, day)), 'amount': round(-lt['_a'], 2), 'overdue': False, 'days_overdue': 0})
    ti = round(sum(x['amount'] for x in ins), 2)
    to = round(sum(x['amount'] for x in outs), 2)
    net = round(ti - to, 2)
    summary = f'Horizon {hy}-{hmo:02d} as of {asof}: inflows {ti:.2f}, outflows {to:.2f}, net {net:.2f}; opening balance {opening:.2f}, projected closing {opening + net:.2f}. {len(paid)} supplier invoice(s) already paid, {len(dups)} excluded, {len(overdue)} overdue receivable(s).'
    return {'opening_balance': opening, 'expected_inflows': ins, 'expected_outflows': outs, 'overdue_receivables': overdue, 'paid_supplier_invoices': paid, 'duplicates_excluded': dups, 'net_exposure_estimate': net, 'projected_closing_balance': round(opening + net, 2), 'total_inflows': ti, 'total_outflows': to, 'summary': summary}

import calendar
from datetime import date

def _d(s, n):
    try:
        return date.fromisoformat(str(s)[:10])
    except Exception:
        raise ValueError(f'{n} must be an ISO date YYYY-MM-DD, got {s!r}')

def _num(x):
    try:
        return float(x)
    except Exception:
        return 0.0

def _r(x):
    return round(x + 0.0, 2)

def _risk(days):
    return 0.8 if days <= 30 else 0.5 if days <= 60 else 0.3 if days <= 90 else 0.1

def _addm(y, m, k):
    t = y * 12 + m - 1 + k
    return t // 12, t % 12 + 1

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'customer_invoices', 'bank_transactions', 'as_of_date', 'horizon_month'):
        if k not in inp:
            raise ValueError(f'missing field {k}')
    for k in ('supplier_invoices', 'customer_invoices', 'bank_transactions'):
        if not isinstance(inp[k], list):
            raise ValueError(f'{k} must be a list')
    asof = _d(inp['as_of_date'], 'as_of_date')
    try:
        hy, hm = [int(p) for p in str(inp['horizon_month']).split('-')[:2]]
        end = date(hy, hm, calendar.monthrange(hy, hm)[1])
    except Exception:
        raise ValueError('horizon_month must be YYYY-MM')
    if end < asof:
        raise ValueError('horizon_month is before as_of_date')
    bank = []
    for i, t in enumerate(inp['bank_transactions']):
        try:
            bank.append((_d(t.get('date'), 'bank date'), i, t))
        except ValueError:
            continue
    bank.sort(key=lambda x: (x[0], x[1]))
    opening = 0.0
    for dt, _, t in bank:
        if dt <= asof and t.get('balance') is not None:
            opening = _num(t['balance'])
    seen = {}
    sup = []
    dups = []
    for inv in inp['supplier_invoices']:
        key = (str(inv.get('supplier', '')).strip().lower(), str(inv.get('invoice_number', '')).strip().lower())
        if key in seen:
            dups.append({'invoice_number': inv.get('invoice_number'), 'supplier': inv.get('supplier'), 'total': inv.get('total'), 'reason': 'resent/duplicate of already listed invoice'})
            continue
        seen[key] = 1
        sup.append(inv)
    paid = []
    unpaid = []
    dblpay = []
    used = set()
    for inv in sup:
        tot = _num(inv.get('total'))
        vs = str(inv.get('vs') or '').strip()
        num = str(inv.get('invoice_number') or '').lower()
        hits = []
        for dt, i, t in bank:
            a = _num(t.get('amount'))
            if a >= 0:
                continue
            msg = str(t.get('message') or '').lower()
            tv = str(t.get('vs') or '').strip()
            ok = (vs and tv == vs) or (num and num in msg) or t.get('matched_invoice') == inv.get('invoice_number')
            if not ok and abs(abs(a) - tot) < 0.01 and tot > 0:
                ok = True
            if ok and abs(abs(a) - tot) < 0.01:
                hits.append((dt, i, t))
        if hits:
            for h in hits:
                used.add(h[1])
            paid.append({'invoice_number': inv.get('invoice_number'), 'supplier': inv.get('supplier'), 'total': tot, 'paid_date': hits[0][0].isoformat()})
            if len(hits) > 1:
                dblpay.append({'invoice_number': inv.get('invoice_number'), 'supplier': inv.get('supplier'), 'total': tot, 'payment_dates': [h[0].isoformat() for h in hits], 'possible_overpayment': _r(tot * (len(hits) - 1))})
        else:
            unpaid.append(inv)
    out = []
    for inv in unpaid:
        due = _d(inv.get('due_date') or inv.get('date'), 'due_date')
        if due > end:
            continue
        late = due < asof
        out.append({'type': 'supplier_invoice', 'description': f"{inv.get('supplier')} {inv.get('invoice_number')}", 'date': (asof if late else due).isoformat(), 'due_date': due.isoformat(), 'amount': _r(_num(inv.get('total'))), 'status': 'overdue_pay_now' if late else 'due_in_period'})
    groups = {}
    for dt, i, t in bank:
        a = _num(t.get('amount'))
        if a >= 0 or i in used or t.get('matched_invoice'):
            continue
        groups.setdefault(str(t.get('counterparty') or '').strip().lower(), []).append((dt, a, t))
    for g in groups.values():
        name = g[0][2].get('counterparty')
        months = {(d.year, d.month) for d, _, _ in g}
        first = min(months)
        last = g[-1]
        day = last[0].day
        y, m = first
        while (y, m) <= (hy, hm):
            if (y, m) not in months:
                dd = date(y, m, min(day, calendar.monthrange(y, m)[1]))
                if dd <= end:
                    past = dd < asof
                    out.append({'type': 'recurring', 'description': f"{name} {last[2].get('message') or ''}".strip(), 'date': dd.isoformat(), 'amount': _r(abs(last[1])), 'status': 'missing_past_run' if past else 'scheduled'})
            y, m = _addm(y, m, 1)
    out.sort(key=lambda x: x['date'])
    inflows = []
    overdue = []
    for c in inp['customer_invoices']:
        if c.get('paid'):
            continue
        due = _d(c.get('due_date'), 'due_date')
        amt = _num(c.get('amount_czk'))
        if due < asof:
            days = (asof - due).days
            p = _risk(days)
            overdue.append({'invoice_number': c.get('invoice_number'), 'customer': c.get('customer'), 'due_date': due.isoformat(), 'days_overdue': days, 'amount': _r(amt), 'collection_probability': p, 'risk_adjusted_amount': _r(amt * p)})
        elif due <= end:
            inflows.append({'invoice_number': c.get('invoice_number'), 'customer': c.get('customer'), 'date': due.isoformat(), 'amount': _r(amt)})
    inflows.sort(key=lambda x: x['date'])
    tin = sum(x['amount'] for x in inflows)
    tout = sum(x['amount'] for x in out)
    tow = sum(x['risk_adjusted_amount'] for x in overdue)
    toa = sum(x['amount'] for x in overdue)
    net = tin + tow - tout
    closing = opening + net
    scen = {'conservative': _r(opening + tin - tout), 'expected': _r(closing), 'optimistic': _r(opening + tin + toa - tout)}
    summ = f'From {asof} to {end}: opening {_r(opening)}, inflows due {_r(tin)}, overdue receivables {_r(toa)} (risk-adjusted {_r(tow)}), outflows {_r(tout)}, expected closing {_r(closing)}. {len(dups)} duplicate invoices excluded, {len(dblpay)} possible double payments.'
    return {'opening_balance': _r(opening), 'expected_inflows': inflows, 'expected_outflows': out, 'overdue_receivables': overdue, 'paid_supplier_invoices': paid, 'duplicates_excluded': dups, 'possible_duplicate_payments': dblpay, 'net_exposure_estimate': _r(net), 'projected_closing_balance_estimate': _r(closing), 'scenarios': scen, 'summary': summ}

import csv, io, os, re
from datetime import datetime


def _num(s):
    if s is None:
        return None
    t = re.sub(r'[\s\u00a0\u202f]', '', str(s)).replace('Kč', '')
    if not t:
        return None
    if ',' in t:
        t = t.replace('.', '').replace(',', '.')
    try:
        return float(t)
    except ValueError:
        return None


def _date(s):
    s = (s or '').strip()
    for f in ('%d.%m.%Y', '%d. %m. %Y', '%Y-%m-%d', '%d/%m/%Y'):
        try:
            return datetime.strptime(s, f).date().isoformat()
        except ValueError:
            pass
    return None


def _read(path):
    raw = open(path, 'rb').read()
    try:
        t = raw.decode('utf-8-sig')
    except UnicodeDecodeError:
        t = raw.decode('cp1250', errors='replace')
    first = t.split('\n', 1)[0]
    delim = ';' if first.count(';') >= first.count(',') else ','
    rows = list(csv.DictReader(io.StringIO(t), delimiter=delim))
    return [{(k or '').strip(): (v or '').strip() for k, v in r.items()} for r in rows]


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('input must contain a non-empty string field folder')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    out = {'bank_transactions': [], 'customer_invoices': [], 'errors': []}
    p = os.path.join(base, 'bank_statement.csv')
    if os.path.exists(p):
        for i, r in enumerate(_read(p), 2):
            a = _num(r.get('Částka'))
            d = _date(r.get('Datum'))
            if a is None or d is None:
                out['errors'].append('bank_statement.csv line %d unparsable' % i)
                continue
            out['bank_transactions'].append({
                'date': d, 'amount': a, 'currency': r.get('Měna') or 'CZK',
                'counterparty': r.get('Protistrana', ''), 'variable_symbol': r.get('VS', ''),
                'message': r.get('Zpráva', ''), 'balance': _num(r.get('Zůstatek'))})
    else:
        out['errors'].append('bank_statement.csv missing')
    p = os.path.join(base, 'customer_invoices.csv')
    if os.path.exists(p):
        for i, r in enumerate(_read(p), 2):
            a = _num(r.get('castka_kc'))
            if a is None or not r.get('cislo_faktury'):
                out['errors'].append('customer_invoices.csv line %d unparsable' % i)
                continue
            out['customer_invoices'].append({
                'invoice_number': r['cislo_faktury'], 'customer': r.get('odberatel', ''),
                'issue_date': _date(r.get('datum_vystaveni')),
                'due_date': _date(r.get('datum_splatnosti')), 'amount_czk': a})
    else:
        out['errors'].append('customer_invoices.csv missing')
    return out

import re
from datetime import date, datetime
from calendar import monthrange
from dateutil import parser as dp

def _d(v, name):
    try:
        return dp.parse(str(v)).date()
    except Exception:
        raise ValueError(f'invalid date in {name}: {v!r}')

def _digits(s):
    return re.sub(r'\D', '', str(s or '')).lstrip('0')

def _num(v):
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).replace(' ', '').replace('\xa0', '').replace(',', '.'))
    except Exception:
        return 0.0

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'bank_transactions', 'customer_invoices'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    asof = _d(inp['as_of_date'], 'as_of_date') if inp.get('as_of_date') else date.today()
    tm = inp.get('target_month')
    if tm:
        if not re.fullmatch(r'\d{4}-\d{2}', str(tm)) or not 1 <= int(str(tm)[5:]) <= 12:
            raise ValueError('target_month must be YYYY-MM')
        ty, tmo = int(tm[:4]), int(tm[5:])
    else:
        ty, tmo = (asof.year + (asof.month == 12), asof.month % 12 + 1)
    mstart = date(ty, tmo, 1)
    mend = date(ty, tmo, monthrange(ty, tmo)[1])
    focus = str(inp.get('focus') or 'all').lower()
    skipped = []
    bank = []
    for i, t in enumerate(inp['bank_transactions']):
        try:
            bank.append(dict(i=i, id=f'bank:{i}', date=_d(t['date'], 'bank'), amt=_num(t.get('amount')), vs=_digits(t.get('variable_symbol')), cp=str(t.get('counterparty') or ''), bal=t.get('balance')))
        except Exception as e:
            skipped.append(f'bank:{i}: {e}')
    opening = 0.0
    dated = [b for b in bank if b['bal'] is not None]
    if dated:
        opening = _num(max(dated, key=lambda b: (b['date'], b['i']))['bal'])
    overdue, inflows, outflows = [], [], []
    if focus in ('all', 'receivables', 'inflows'):
        for c in inp['customer_invoices']:
            try:
                num = c.get('invoice_number')
                due = _d(c['due_date'], 'due_date')
                amt = _num(c.get('amount_czk', c.get('total')))
                key = _digits(num)
                ms = [b for b in bank if b['amt'] > 0 and key and b['vs'] == key]
                paid = sum(b['amt'] for b in ms)
                rem = round(amt - paid, 2)
                if rem <= 0.01:
                    continue
                rec = dict(invoice_number=num, customer=c.get('customer'), due_date=str(due), amount=amt, paid=round(paid, 2), outstanding=rem, record_ids=[str(num)] + [b['id'] for b in ms])
                if due < asof:
                    rec['days_overdue'] = (asof - due).days
                    overdue.append(rec)
                elif due <= mend:
                    rec['expected_date'] = str(due)
                    inflows.append(rec)
            except Exception as e:
                skipped.append(f'customer_invoice {c.get("invoice_number") if isinstance(c, dict) else c}: {e}')
    paidvs = set()
    if focus in ('all', 'payables', 'outflows'):
        outs = [b for b in bank if b['amt'] < 0]
        for s in inp['supplier_invoices']:
            try:
                key = _digits(s.get('vs'))
                due = _d(s['due_date'], 'due_date')
                tot = _num(s.get('total'))
                ms = [b for b in outs if key and b['vs'] == key]
                if key:
                    paidvs.add(key)
                paid = -sum(b['amt'] for b in ms)
                rem = round(tot - paid, 2)
                if rem <= 0.01 or due > mend:
                    continue
                outflows.append(dict(type='supplier_invoice', supplier=s.get('supplier'), invoice_number=s.get('invoice_number'), due_date=str(due), amount=rem, overdue=due < asof, record_ids=[str(s.get('invoice_number'))] + [b['id'] for b in ms]))
            except Exception as e:
                skipped.append(f'supplier_invoice {s.get("invoice_number") if isinstance(s, dict) else s}: {e}')
        groups = {}
        for b in outs:
            if b['vs'] in paidvs and b['vs']:
                continue
            groups.setdefault((b['cp'], round(b['amt'])), []).append(b)
        for (cp, a), g in groups.items():
            months = {(b['date'].year, b['date'].month) for b in g}
            if len(months) >= 2:
                outflows.append(dict(type='recurring_bank_outflow', counterparty=cp, amount=round(-g[0]['amt'], 2), expected_month=f'{ty:04d}-{tmo:02d}', occurrences=len(g), record_ids=[b['id'] for b in g]))
    tin = round(sum(r['outstanding'] for r in inflows), 2)
    tout = round(sum(r['amount'] for r in outflows), 2)
    net = round(tin - tout, 2)
    tod = round(sum(r['outstanding'] for r in overdue), 2)
    summary = f'ESTIMATE for {ty:04d}-{tmo:02d} as of {asof}: expected inflows {tin}, outflows {tout}, net exposure {net}; opening balance {opening}; {len(overdue)} overdue receivables totalling {tod} (not counted in inflows).'
    if skipped:
        summary += f' Skipped {len(skipped)} unparseable records.'
    return dict(overdue_receivables=overdue, expected_inflows=inflows, expected_outflows=outflows, net_exposure_estimate=net, opening_balance=opening, total_overdue_receivables=tod, skipped=skipped, is_estimate=True, summary=summary)

