    summary = f'ESTIMATE for {ty:04d}-{tmo:02d} as of {asof}: expected inflows {tin}, outflows {tout}, net exposure {net}; opening balance {opening}; {len(overdue)} overdue receivables totalling {tod} (not counted in inflows).'
    if skipped:
        summary += f' Skipped {len(skipped)} unparseable records.'
    return dict(overdue_receivables=overdue, expected_inflows=inflows, expected_outflows=outflows, net_exposure_estimate=net, opening_balance=opening, total_overdue_receivables=tod, skipped=skipped, is_estimate=True, summary=summary)

import re
from datetime import date, datetime

def _d(s):
    try:
        return datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
    except Exception:
        return None

def _digits(s):
    return re.sub(r'\D', '', str(s or ''))

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'bank_transactions', 'customer_invoices'):
        if not isinstance(inp.get(k), list):
            raise ValueError(k + ' must be a list')
    tm = str(inp.get('target_month') or '')
    if not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', tm):
        raise ValueError('target_month must be YYYY-MM')
    if inp.get('as_of_date'):
        asof = _d(inp['as_of_date'])
        if not asof:
            raise ValueError('as_of_date must be YYYY-MM-DD')
    else:
        asof = date.today()
    bank = [b for b in inp['bank_transactions'] if isinstance(b, dict)]
    skipped = []
    used = set()

    def paid(ref, vs, sign):
        rd, vd = _digits(ref), _digits(vs)
        for i, b in enumerate(bank):
            if i in used:
                continue
            try:
                amt = float(b.get('amount') or 0)
            except Exception:
                continue
            if amt * sign <= 0:
                continue
            bv = _digits(b.get('variable_symbol'))
            msg = str(b.get('message') or '')
            if (bv and (bv == rd or bv == vd) and bv) or (ref and str(ref) in msg):
                used.add(i)
                return True
        return False

    overdue, inflows, outflows, carried = [], [], [], []
    for c in inp['customer_invoices']:
        dd = _d(c.get('due_date')) if isinstance(c, dict) else None
        if not dd:
            skipped.append({'record': str(c)[:80], 'reason': 'bad customer invoice'})
            continue
        if paid(c.get('invoice_number'), None, 1):
            continue
        rec = {'id': c.get('invoice_number'), 'party': c.get('customer'), 'due_date': str(dd), 'amount': float(c.get('amount_czk') or 0), 'direction': 'inflow'}
        if dd < asof:
            overdue.append(dict(rec, days_overdue=(asof - dd).days))
        if dd.strftime('%Y-%m') == tm:
            inflows.append(dict(rec, type='customer_invoice'))
        elif dd.strftime('%Y-%m') < tm:
            carried.append(dict(rec, label='unpaid, due before target month; not in net estimate'))
    for s in inp['supplier_invoices']:
        dd = _d(s.get('due_date')) if isinstance(s, dict) else None
        if not dd:
            skipped.append({'record': str(s)[:80], 'reason': 'bad supplier invoice'})
            continue
        if paid(s.get('invoice_number'), s.get('vs'), -1):
            continue
        rec = {'id': s.get('invoice_number'), 'party': s.get('supplier'), 'due_date': str(dd), 'amount': float(s.get('total') or 0), 'direction': 'outflow'}
        if dd.strftime('%Y-%m') == tm:
            outflows.append(dict(rec, type='supplier_invoice'))
        elif dd.strftime('%Y-%m') < tm:
            carried.append(dict(rec, label='unpaid, due before target month; not in net estimate'))
    groups = {}
    for i, b in enumerate(bank):
        d = _d(b.get('date'))
        try:
            a = float(b.get('amount'))
        except Exception:
            continue
        if a >= 0 or not d or i in used or d.strftime('%Y-%m') >= tm:
            continue
        k = (b.get('counterparty'), b.get('message'), a)
        groups.setdefault(k, []).append(d)
    for (cp, msg, a), ds in groups.items():
        if len({x.strftime('%Y-%m') for x in ds}) >= 2:
            outflows.append({'id': 'recurring:' + str(cp), 'party': cp, 'description': msg, 'amount': -a, 'direction': 'outflow', 'type': 'recurring', 'last_seen': str(max(ds))})
    opening = 0.0
    dated = sorted([b for b in bank if _d(b.get('date')) and _d(b.get('date')) <= asof and b.get('balance') is not None], key=lambda b: _d(b['date']))
    if dated:
        opening = float(dated[-1]['balance'])
    tin = sum(x['amount'] for x in inflows)
    tout = sum(x['amount'] for x in outflows)
    net = round(tin - tout, 2)
    tov = sum(x['amount'] for x in overdue)
    cs = sum(x['amount'] for x in carried if x['direction'] == 'outflow')
    summary = ('Estimated net cash flow for %s (inflows %.2f minus outflows %.2f, only items due in that month): %.2f. Overdue receivables as of %s: %d totalling %.2f. Earlier-month unpaid items reported separately (%d, payables %.2f), not included in net.' % (tm, tin, tout, net, asof, len(overdue), tov, len(carried), cs))
    out = {'overdue_receivables': overdue, 'expected_inflows': inflows, 'expected_outflows': outflows, 'carried_over_before_target_month': carried, 'net_exposure_estimate': net, 'opening_balance': opening, 'summary': summary}
    if skipped:
        out['skipped_records'] = skipped
    return out

import re
from datetime import date, timedelta
from statistics import median


def _d(s, name):
    try:
        return date.fromisoformat(str(s)[:10])
    except Exception:
        raise ValueError(f'{name} must be an ISO date YYYY-MM-DD, got {s!r}')


def _digits(s):
    return re.sub(r'\D', '', str(s or ''))


def _num(x):
    try:
        return float(x)
    except Exception:
        return None


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'bank_transactions', 'customer_invoices'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    as_of = _d(inp.get('as_of_date'), 'as_of_date')
    tm = str(inp.get('target_month') or '')
    if not re.fullmatch(r'\d{4}-\d{2}', tm) or not 1 <= int(tm[5:]) <= 12:
        raise ValueError('target_month must be YYYY-MM')
    ms = date(int(tm[:4]), int(tm[5:]), 1)
    me = (ms.replace(day=28) + timedelta(days=4)).replace(day=1) - timedelta(days=1)
    notes = []
    bank = []
    for t in inp['bank_transactions']:
        try:
            bank.append((_d(t.get('date'), 'bank date'), float(t.get('amount')), t))
        except Exception:
            notes.append(f'Skipped unparsable bank transaction: {str(t)[:80]}')
    bank.sort(key=lambda x: x[0])
    used = set()

    def match(ref, vs, amount, sign):
        for i, (d, a, t) in enumerate(bank):
            if i in used or a * sign <= 0:
                continue
            tv = _digits(t.get('variable_symbol'))
            msg = str(t.get('message') or '')
            hit = (vs and tv == vs) or (ref and ref in msg) or (ref and ref in tv and tv)
            if hit:
                used.add(i)
                return d
        return None

    rec_paid, lags_in, unpaid_r = [], [], []
    for c in inp['customer_invoices']:
        try:
            due = _d(c.get('due_date'), 'due_date')
            amt = float(c.get('amount_czk', c.get('total')))
        except Exception as e:
            notes.append(f'Skipped customer invoice {c.get("invoice_number")}: {e}')
            continue
        pd = match(str(c.get('invoice_number') or ''), _digits(c.get('invoice_number')), amt, 1)
        if pd:
            lags_in.append((pd - due).days)
        else:
            unpaid_r.append((c, due, amt))
    lags_out, unpaid_p = [], []
    for s in inp['supplier_invoices']:
        try:
            due = _d(s.get('due_date'), 'due_date')
            amt = float(s.get('total'))
        except Exception as e:
            notes.append(f'Skipped supplier invoice {s.get("invoice_number")}: {e}')
            continue
        pd = match(str(s.get('invoice_number') or ''), _digits(s.get('vs')), amt, -1)
        if pd:
            lags_out.append((pd - due).days)
        else:
            unpaid_p.append((s, due, amt))
    lin = round(median(lags_in)) if lags_in else 0
    lout = round(median(lags_out)) if lags_out else 0
    overdue, nyd, inflows = [], [], []
    for c, due, amt in unpaid_r:
        base = {'invoice_number': c.get('invoice_number'), 'customer': c.get('customer'), 'due_date': due.isoformat(), 'amount': amt}
        exp = max(due + timedelta(days=lin), as_of)
        if due < as_of:
            overdue.append({**base, 'days_overdue': (as_of - due).days})
            status = 'overdue'
        else:
            nyd.append({**base, 'days_until_due': (due - as_of).days})
            status = 'not_yet_due'
        if exp <= me:
            inflows.append({**base, 'status': status, 'expected_date': max(exp, ms).isoformat(), 'amount': amt})
    outflows, payables = [], []
    for s, due, amt in unpaid_p:
        exp = max(due + timedelta(days=lout), as_of)
        inc = exp <= me
        base = {'invoice_number': s.get('invoice_number'), 'supplier': s.get('supplier'), 'due_date': due.isoformat(), 'amount': amt,
                'status': 'overdue' if due < as_of else 'not_yet_due', 'expected_payment_date': max(exp, ms).isoformat() if inc else exp.isoformat(), 'in_target_month': inc}
        payables.append(base)
        if inc:
            outflows.append({**base, 'type': 'supplier_invoice'})
    groups = {}
    for i, (d, a, t) in enumerate(bank):
        if a < 0 and i not in used:
            groups.setdefault(str(t.get('counterparty') or 'unknown'), []).append((d, a))
    for cp, v in groups.items():
        months = {(d.year, d.month) for d, _ in v}
        amt = abs(median(a for _, a in v))
        outflows.append({'type': 'recurring', 'counterparty': cp, 'amount': round(amt, 2), 'months_observed': len(months), 'expected_payment_date': ms.isoformat()})
    if any(len({(d.year, d.month) for d, _ in v}) < 2 for v in groups.values()):
        notes.append('Some recurring outflows were seen in only one month; assumed to repeat monthly.')
    if not bank:
        notes.append('No bank history; lags default to 0 and no recurring outflows.')
    opening = 0.0
    for d, a, t in reversed(bank):
        b = _num(t.get('balance'))
        if b is not None:
            opening = b
            break
    tin = sum(x['amount'] for x in inflows)
    tout = sum(x['amount'] for x in outflows)
    net = round(tin - tout, 2)
    assumptions = [
        f'Customer collection lag vs due date: {lin} days (median of {len(lags_in)} matched payments).',
        f'Supplier payment lag vs due date: {lout} days (median of {len(lags_out)} matched payments).',
        'Overdue receivables (due before as_of_date) are assumed collected by end of target month, not earlier than its start.',
        'Not-yet-due items are included only if due date plus lag falls on or before target month end; earlier ones are placed at month start.',
        'Unpaid payables are paid at due date plus lag, never before as_of_date; earlier ones are placed at month start.',
        'Bank outflows not matching supplier invoices are treated as monthly recurring at their median amount.',
        'net_exposure_estimate = expected inflows - expected outflows for the target month; opening_balance is the last bank balance and is not included.']
    summary = (f'{tm}: expected inflows {tin:.2f}, outflows {tout:.2f}, net estimate {net:.2f} (opening balance {opening:.2f} not included). '
               f'{len(overdue)} overdue and {len(nyd)} not-yet-due receivables unpaid; {len(payables)} unpaid payables.')
    return {'overdue_receivables': overdue, 'not_yet_due_receivables': nyd, 'expected_inflows': inflows, 'expected_outflows': outflows,
            'unpaid_payables': payables, 'opening_balance': opening, 'net_exposure_estimate': net, 'assumptions': assumptions, 'notes': notes, 'summary': summary}

import csv, io, os, re
from datetime import datetime


def _date(s):
    s = (s or '').strip()
    for f in ('%Y-%m-%d', '%d.%m.%Y', '%d. %m. %Y', '%d/%m/%Y', '%Y/%m/%d'):
        try:
            return datetime.strptime(s, f).date().isoformat()
        except ValueError:
            pass
    return None


def _read(path):
    raw = open(path, 'rb').read()
    try:
        t = raw.decode('utf-8-sig')
    except UnicodeDecodeError:
        t = raw.decode('cp1250', errors='replace')
    first = t.split('\n', 1)[0]
    delim = ';' if first.count(';') > first.count(',') else ','
    rows = list(csv.DictReader(io.StringIO(t), delimiter=delim))
    return [{(k or '').strip().lower(): (v or '').strip() for k, v in r.items()} for r in rows]


def _bound(v, name):
    if v is None or v == '':
        return None
    if not isinstance(v, str):
        raise ValueError(name + ' must be a string')
    d = _date(v)
    if d is None:
        raise ValueError(name + ' is not a valid date: ' + v)
    return d


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('input must contain a non-empty string field folder')
    df = _bound(inp.get('date_from'), 'date_from')
    dt = _bound(inp.get('date_to'), 'date_to')
    if df and dt and df > dt:
        raise ValueError('date_from is after date_to')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    p = os.path.join(base, 'customer_feedback.csv')
    out = {'feedback': [], 'errors': []}
    if not os.path.exists(p):
        out['errors'].append('customer_feedback.csv missing')
        return out
    n = 0
    for i, r in enumerate(_read(p), 2):
        d = _date(r.get('date'))
        if d is None or not r.get('text'):
            out['errors'].append('customer_feedback.csv line %d unparsable' % i)
            continue
        if (df and d < df) or (dt and d > dt):
            continue
        n += 1
        out['feedback'].append({'id': n, 'date': d, 'customer': r.get('customer', ''),
                                'channel': r.get('channel', ''), 'text': r.get('text', '')})
    return out

import re
from datetime import date, datetime
from dateutil import parser as dp


def _d(v, name):
    if isinstance(v, date) and not isinstance(v, datetime):
        return v
    if isinstance(v, datetime):
        return v.date()
    if not isinstance(v, str) or not v.strip():
        raise ValueError(f'invalid date for {name}: {v!r}')
    try:
        return dp.parse(v.strip(), dayfirst=False).date() if re.match(r'\d{4}-', v.strip()) else dp.parse(v.strip(), dayfirst=True).date()
    except Exception:
        raise ValueError(f'invalid date for {name}: {v!r}')


def _num(v):
    if v is None or v == '':
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).replace('\xa0', '').replace(' ', '')
    if ',' in s and '.' in s:
        s = s.replace('.', '').replace(',', '.') if s.rfind(',') > s.rfind('.') else s.replace(',', '')
    else:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return None


def _digits(s):
    return re.sub(r'\D', '', str(s or '')).lstrip('0')


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    invs = inp.get('customer_invoices')
    txs = inp.get('bank_transactions')
    if not isinstance(invs, list) or not isinstance(txs, list):
        raise ValueError('customer_invoices and bank_transactions must be arrays')
    as_of = _d(inp['as_of_date'], 'as_of_date') if inp.get('as_of_date') else date.today()
    minl = inp.get('min_days_late', 1)
    if not isinstance(minl, int):
        raise ValueError('min_days_late must be an integer')
    cf = (inp.get('customer_filter') or '').strip().lower()
    credits = []
    for t in txs:
        if not isinstance(t, dict):
            continue
        a = _num(t.get('amount'))
        if a is None or a <= 0:
            continue
        try:
            td = _d(t.get('date'), 'date')
        except ValueError:
            continue
        if td > as_of:
            continue
        credits.append({'amt': a, 'vs': _digits(t.get('variable_symbol')), 'msg': str(t.get('message') or '') + ' ' + str(t.get('counterparty') or ''), 'left': a})
    overdue, skipped = [], []
    items = []
    for i in invs:
        try:
            num = str(i['invoice_number'])
            items.append((_d(i['due_date'], 'due_date'), num, i, _num(i['amount_czk'])))
        except Exception as e:
            skipped.append({'invoice': i, 'reason': str(e)})
    items.sort(key=lambda x: x[0])
    for due, num, i, amt in items:
        if amt is None:
            skipped.append({'invoice': i, 'reason': 'bad amount'})
            continue
        nd = _digits(num)
        paid = 0.0
        for c in credits:
            if c['left'] <= 0.004:
                continue
            hit = (c['vs'] and nd and (c['vs'] == nd or nd.endswith(c['vs']) and len(c['vs']) >= 6)) or (num.lower() in c['msg'].lower())
            if hit:
                use = min(c['left'], amt - paid)
                if use > 0:
                    c['left'] -= use
                    paid += use
        out = round(amt - paid, 2)
        late = (as_of - due).days
        cust = str(i.get('customer', ''))
        if out > 0.004 and late >= minl and late > 0 and (not cf or cf in cust.lower()):
            overdue.append({'customer': cust, 'invoice_number': num, 'due_date': due.isoformat(), 'days_late': late, 'outstanding_czk': out})
    overdue.sort(key=lambda x: (-x['days_late'], x['invoice_number']))
    bc = {}
    for o in overdue:
        b = bc.setdefault(o['customer'], {'customer': o['customer'], 'invoice_count': 0, 'total_outstanding_czk': 0.0, 'max_days_late': 0})
        b['invoice_count'] += 1
        b['total_outstanding_czk'] = round(b['total_outstanding_czk'] + o['outstanding_czk'], 2)
        b['max_days_late'] = max(b['max_days_late'], o['days_late'])
    by = sorted(bc.values(), key=lambda b: -b['total_outstanding_czk'])
    return {'as_of_date': as_of.isoformat(), 'overdue': overdue, 'total_overdue_czk': round(sum(o['outstanding_czk'] for o in overdue), 2), 'by_customer': by, 'skipped': skipped}

import csv, os, re
from collections import defaultdict


def _num(s):
    s = str(s or '').strip().replace('\xa0', '').replace(' ', '')
    if not s:
        raise ValueError('empty')
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    return float(s)


def _mon(v, name):
    if v is None or v == '':
        return None
    v = str(v).strip()
    if not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', v):
        raise ValueError(f'{name} must be YYYY-MM')
    return v


def _find(folder):
    base = os.path.join('.', 'inbox', folder)
    if not os.path.isdir(base):
        raise ValueError(f'folder not found: {folder}')
    for root, _, files in os.walk(base):
        for f in files:
            if f.lower() == 'sales_2026.csv':
                return os.path.join(root, f)
    raise ValueError('sales_2026.csv not found in folder')


def _read(path):
    txt = open(path, encoding='utf-8-sig', newline='').read()
    first = txt.split('\n', 1)[0]
    d = ';' if first.count(';') > first.count(',') else ','
    import io
    return list(csv.DictReader(io.StringIO(txt), delimiter=d))


def _bw(items, key):
    if not items:
        return None, None
    b = max(items, key=lambda x: x[key])
    w = min(items, key=lambda x: x[key])
    return b, w


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('folder (string) is required')
    fm = _mon(inp.get('from_month'), 'from_month')
    tm = _mon(inp.get('to_month'), 'to_month')
    cf = (inp.get('category_filter') or '').strip().lower()
    cu = (inp.get('customer_filter') or '').strip().lower()
    rows = _read(_find(inp['folder']))
    agg = defaultdict(lambda: [0.0, 0.0, 0])
    skipped = []
    used = 0
    for i, r in enumerate(rows, 2):
        try:
            m = r['month'].strip()
            c = r['category'].strip()
            u = _num(r['units'])
            rev = _num(r['revenue_czk'])
            cust = (r.get('customer') or '').strip()
        except Exception as e:
            skipped.append({'line': i, 'reason': str(e)})
            continue
        if fm and m < fm or tm and m > tm:
            continue
        if cf and c.lower() != cf:
            continue
        if cu and cu not in cust.lower():
            continue
        a = agg[(m, c)]
        a[0] += u
        a[1] += rev
        a[2] += 1
        used += 1
    mbc = [{'month': m, 'category': c, 'units': round(a[0], 2), 'revenue_czk': round(a[1], 2), 'row_count': a[2]}
           for (m, c), a in sorted(agg.items())]
    mt = defaultdict(float)
    ct = defaultdict(float)
    for x in mbc:
        mt[x['month']] += x['revenue_czk']
        ct[x['category']] += x['revenue_czk']
    monthly = [{'month': k, 'revenue_czk': round(v, 2)} for k, v in sorted(mt.items())]
    cats = [{'category': k, 'revenue_czk': round(v, 2)} for k, v in sorted(ct.items())]
    b, w = _bw(monthly, 'revenue_czk')
    per = []
    for c in sorted(ct):
        items = [x for x in mbc if x['category'] == c]
        cb, cw = _bw(items, 'revenue_czk')
        per.append({'category': c,
                    'best_month': {'month': cb['month'], 'revenue_czk': cb['revenue_czk']},
                    'worst_month': {'month': cw['month'], 'revenue_czk': cw['revenue_czk']}})
    return {'monthly_by_category': mbc, 'monthly_totals': monthly, 'category_totals': cats,
            'best_month': b or {}, 'worst_month': w or {}, 'best_worst_by_category': per,
            'source_rows_total': len(rows), 'source_rows_used': used, 'skipped_rows': skipped}

import csv, io, os, re
from datetime import datetime


def _date(s):
