import csv, os, re
from datetime import date, datetime

_FMTS = ('%Y-%m-%d', '%d.%m.%Y', '%d. %m. %Y', '%d/%m/%Y', '%m/%d/%Y', '%Y/%m/%d')


def _pd(s):
    s = (s or '').strip()
    for f in _FMTS:
        try:
            return datetime.strptime(s, f).date()
        except ValueError:
            pass
    return None


def _inp_date(v, name):
    if v in (None, ''):
        return None
    if not isinstance(v, str):
        raise ValueError(f'{name} must be a string')
    d = _pd(v)
    if d is None:
        raise ValueError(f'{name} is not a valid date: {v!r}')
    return d


def _find(folder):
    base = os.path.join('.', 'inbox', folder)
    if not os.path.isdir(base):
        raise ValueError(f'folder not found: {folder}')
    for root, _, files in os.walk(base):
        for fn in sorted(files):
            if fn.lower() == 'customer_feedback.csv':
                return os.path.join(root, fn)
    raise ValueError('customer_feedback.csv not found in folder')


def _read(path):
    raw = open(path, 'rb').read()
    for enc in ('utf-8-sig', 'cp1250', 'latin-1'):
        try:
            return raw.decode(enc)
        except UnicodeDecodeError:
            pass


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    folder = inp.get('folder')
    if not isinstance(folder, str) or not folder.strip():
        raise ValueError('folder is required')
    if '..' in folder.replace('\\', '/').split('/'):
        raise ValueError('invalid folder')
    fd = _inp_date(inp.get('from_date'), 'from_date')
    td = _inp_date(inp.get('to_date'), 'to_date')
    cf = (inp.get('customer_filter') or '').strip().lower()
    chf = (inp.get('channel_filter') or '').strip().lower()
    text = _read(_find(folder))
    try:
        dialect = csv.Sniffer().sniff(text[:2000], delimiters=',;\t')
        delim = dialect.delimiter
    except csv.Error:
        delim = ','
    rd = csv.DictReader(text.splitlines(True) if False else __import__('io').StringIO(text, newline=''), delimiter=delim)
    rd.fieldnames = [(h or '').strip().lower() for h in (rd.fieldnames or [])]
    records, skipped = [], []
    n = 0
    for row in rd:
        if not any((v or '').strip() for v in row.values() if isinstance(v, str)):
            continue
        n += 1
        raw_d = (row.get('date') or '').strip()
        d = _pd(raw_d)
        rec = {'id': n, 'date': d.isoformat() if d else raw_d,
               'customer': (row.get('customer') or '').strip(),
               'channel': (row.get('channel') or '').strip(),
               'text': (row.get('text') or '').strip()}
        if (fd or td) and d is None:
            skipped.append({'id': n, 'reason': 'unparseable date'})
            continue
        if fd and d < fd:
            continue
        if td and d > td:
            continue
        if cf and cf not in rec['customer'].lower():
            continue
        if chf and chf != rec['channel'].lower():
            continue
        records.append(rec)
    out = {'records': records}
    if skipped:
        out['skipped'] = skipped
    return out

import re
from collections import OrderedDict


def _key(v):
    return str(v).strip()


def run(inp: dict) -> dict:
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    records = inp.get('records')
    labels = inp.get('labels')
    if not isinstance(records, list) or not isinstance(labels, list):
        raise ValueError('records and labels must be lists')
    top_n = inp.get('top_n', 5)
    if top_n is None:
        top_n = 5
    if isinstance(top_n, bool) or not isinstance(top_n, int) or top_n < 1:
        raise ValueError('top_n must be a positive integer')
    by_id = {}
    for pos, r in enumerate(records, start=1):
        if isinstance(r, dict):
            rid = r.get('id', pos)
            by_id[_key(rid)] = r
    groups = OrderedDict()
    skipped = []
    total = 0
    for lab in labels:
        if not isinstance(lab, dict):
            skipped.append(lab)
            continue
        if _key(lab.get('sentiment', '')).lower() != 'complaint':
            continue
        theme = _key(lab.get('theme', '')) or 'unlabelled'
        rid = lab.get('id')
        rec = by_id.get(_key(rid))
        if rec is None:
            skipped.append(rid)
            continue
        total += 1
        g = groups.setdefault(theme, {'ids': [], 'cust': [], 'dates': [], 'texts': []})
        g['ids'].append(rec.get('id', rid))
        c = rec.get('customer')
        if c is not None and c not in g['cust']:
            g['cust'].append(c)
        d = rec.get('date')
        if d is not None and d not in g['dates']:
            g['dates'].append(d)
        t = rec.get('text')
        if t is not None and t not in g['texts']:
            g['texts'].append(t)
    items = sorted(groups.items(), key=lambda kv: (-len(kv[1]['ids']), kv[0]))[:top_n]
    ranking = []
    for theme, g in items:
        n = len(g['ids'])
        ranking.append({
            'theme': theme,
            'count': n,
            'share': round(n / total, 4) if total else 0.0,
            'record_ids': g['ids'],
            'customers': g['cust'],
            'dates': sorted(g['dates']),
            'example_texts': g['texts'],
        })
    return {'ranking': ranking, 'total_complaints': total, 'unmatched_labels': len(skipped)}
